// Іова — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Був чоловік у землі Уц, ім’я його Іов; і був чоловік цей непорочний, справедливий і богобоязкий і віддалявся від зла.","І народилися у нього сім синів і три дочки.","Майна у нього було: сім тисяч дрібної худоби, три тисячі верблюдів, п’ятсот пар волів і п’ятсот ослиць і дуже багато прислуги; і був чоловік цей знаменитіший за всіх синів Сходу.","Сини його сходилися, робили бенкети кожен у своєму домі у свій день, і посилали і запрошували трьох сестер своїх їсти і пити з ними.","Коли коло бенкетних днів звершувалося, Іов посилав за ними й освячував їх і, встаючи рано-вранці, підносив всепалення за числом усіх їх [і одного тельця за гріх про душі їхні]. Бо говорив Іов: може, сини мої згрішили і похулили Бога в серці своєму. Так робив Іов в усі такі дні.","І був день, коли прийшли сини Божі стати перед Господом; між ними прийшов і сатана.","І сказав Господь сатані: звідки ти прийшов? І відповів сатана Господу і сказав: я ходив по землі й обійшов її.","І сказав Господь сатані: чи звернув ти увагу твою на раба Мого Іова? бо немає такого, як він, на землі: чоловік непорочний, справедливий, богобоязкий і віддаляється від зла.","І відповів сатана Господу і сказав: хіба даром богобоязкий Іов?","Чи не Ти навколо відгородив його і дім його й усе, що у нього? Діло рук його Ти благословив, і стада його поширюються по землі;","але простягни руку Твою і торкнися всього, що у нього, — чи благословить він Тебе?","І сказав Господь сатані: ось, усе, що у нього, у руці твоїй; тільки на нього не простягай руки твоєї. І відійшов сатана від лиця Господа.","І був день, коли сини його і дочки його їли і вино пили в домі первородного брата свого.","І ось, приходить вісник до Іова і говорить:","воли орали, й ослиці паслися поряд з ними, як напали савеяни і взяли їх, а слуг уразили вістрям меча; і врятувався тільки я один, щоб сповістити тебе.","Ще він говорив, як приходить інший і каже: вогонь Божий упав з неба й спалив овець і слуг і пожер їх; і врятувався тільки я один, щоб сповістити тебе.","Ще він говорив, як приходить інший і каже: халдеї розташувалися трьома загонами і кинулися на верблюдів і взяли їх, а слуг уразили вістрям меча; і врятувався тільки я один, щоб сповістити тебе.","Ще цей говорив, приходить інший і каже: сини твої і дочки твої їли і пили вино у домі первородного брата свого;","і ось, великий вітер прийшов з пустелі й охопив чотири кути дому, і дім упав на отроків, і вони померли; і врятувався тільки я один, щоб сповістити тебе.","Тоді Іов встав і роздер верхній одяг свій, обстриг голову свою й упав на землю і поклонився","і сказав: нагим я вийшов із утроби матері моєї, нагим і повернуся. Господь дав, Господь і взяв; [як угодно було Господу, так і зробилося;] нехай буде ім’я Господнє благословенне!","У всьому цьому не згрішив Іов і не промовив нічого нерозумного про Бога."],"x":{"1":"36.14.14:20|55.5.11","5":"1.19.10|3.11.18","6":"50.18.10|10.22.21|76.12.10","21":"27.5.14|29.7.6|29.6.7"}},{"v":["Був день, коли прийшли сини Божі стати перед Господом; між ними прийшов і сатана стати перед Господом.","І сказав Господь сатані: звідки ти прийшов? І відповів сатана Господу і сказав: я ходив по землі й обійшов її.","І сказав Господь сатані: чи звернув ти увагу твою на раба Мого Іова? бо немає такого, як він, на землі: чоловік непорочний, справедливий, богобоязкий і віддаляється від зла, і досі твердий у своїй непорочності; а ти збуджував Мене проти нього, щоб погубити його невинно.","І відповів сатана Господу і сказав: шкіру за шкіру, а за життя своє віддасть людина усе, що є у неї;","але простягни руку Твою і торкнися кістки його і плоті його, — чи благословить він Тебе?","І сказав Господь сатані: ось, він у руках твоїх, тільки душу його збережи.","І відійшов сатана від лиця Господа й уразив Іова проказою лютою від підошви ноги його по саме тім’я його.","І взяв він собі черепок, щоб шкребти себе ним, і сів у попіл [поза селищем].","І сказала йому дружина його: ти все ще твердий у непорочності твоїй! похули Бога і помри*.","Але він сказав їй: ти говориш як одна з безумних: невже добре ми будемо приймати від Бога, а лихого не будемо приймати? В усьому цьому не згрішив Іов вустами своїми.","І почули троє друзів Іова про всі ці біди, які осягли його, і пішли кожен зі свого місця: Елифаз феманитянин, Вилдад савхеянин і Софар наамитянин, і зійшлися, щоб іти разом тужити з ним і втішати його.","І, піднявши очі свої здаля, вони не впізнали його; і піднесли голос свій і заридали; і роздер кожен верхній одяг свій, і кидали порох над головами своїми до неба.","І сиділи з ним на землі сім днів і сім ночей; і ніхто не говорив йому ні слова, тому що бачили, що страждання його дуже великі."],"x":{"1":"24.1.6","3":"24.1.1","5":"24.1.11","7":"24.7.5","9":"18.2.14","10":"27.7.14|24.1.22","11":"0.25.3"},"n":{"9":["Цей стих за перекладом 70-ти: Після довгого часу сказала йому дружина його: доки ти будеш терпіти? Ось, почекаю ще трохи в надії на спасіння моє. Бо загинули з землі пам’ять твоя, сини і дочки, болісті утроби моєї і труди, якими дарма трудилася. Сам ти сидиш у смороді черви, проводячи ніч без покрова, а я блукаю і служу, переходжу з місця на місце, з дому в дім, очікуючи, коли зайде сонце, щоб заспокоїтися від трудів моїх і хвороб, які нині пригнічують мене. Але скажи якесь слово до Бога і помри."]}},{"v":["Після того відкрив Іов вуста свої і прокляв день свій.","І почав Іов і сказав:","згинь день, у який я народився, і ніч, у яку сказано: зачалася людина!","День той нехай буде темрявою; нехай не шукає його Бог з висоти, і нехай не засяє над ним світло!","Нехай затьмарить його темрява і тінь смертна, нехай обійме його хмара, нехай страшаться його, як палючої спеки!","Ніч та, — нехай володіє нею морок, нехай не рахується вона в днях року, нехай не ввійде у число місяців!","О! ніч та — нехай буде вона безлюдна; нехай не ввійде в неї радість!","Нехай проклянуть її ті, що проклинають день, здатні розбудити левиафана!","Нехай померкнуть зірки світанку її: нехай чекає вона світла, і воно не приходить, і нехай не побачить вона вій денниці","за те, що не зачинила дверей утроби матері моєї і не приховала горя від очей моїх!","Чому я не помер, виходячи з утроби, і не помер, коли вийшов з утроби?","Навіщо прийняли мене коліна? навіщо було мені годуватися грудьми?","Тепер би лежав я і спочивав; спав би, і мені було б спокійно","з царями і радниками землі, які забудовували для себе пустелі,","або з князями, у яких було золото, і які наповнювали доми свої сріблом;","або, як викидень прихований, я не існував би, як немовлята, які не побачили світла.","Там беззаконні перестають наводити страх, і там відпочивають виснажені в силі.","Там в’язні разом насолоджуються спокоєм і не чують криків приставника.","Малий і великий там рівні, і раб вільний від господаря свого.","Навіщо дано страднику світло, і життя засмученим душею,","які чекають на смерть, і немає її, які викопали б її охочіше, ніж скарб,","зраділи б до захвату, захоплювалися б, що знайшли гріб?","Навіщо дано світло людині, путь якої закрита, і яку Бог оточив мороком?","Зітхання мої попереджають хліб мій, і стогони мої ллються, як вода,","бо жахливе, чого я жахався, те й осягло мене; і чого я боявся, те і прийшло до мене.","Немає мені миру, немає спокою, немає відради: спіткало нещастя."],"x":{"3":"32.20.14","8":"24.40.20","13":"27.4.3","21":"76.9.6","25":"26.28.14"}},{"v":["І відповів Елифаз феманитянин і сказав:","якщо спробуємо ми сказати тобі слово, — чи не тяжко буде тобі? Утім, хто може заборонити слову!","Ось, ти наставляв багатьох і опущені руки підтримував,","того, хто падав, піднімали слова твої, і коліна, що гнулися, ти укріпляв.","А тепер дійшло до тебе, і ти знеміг; торкнулося тебе, і ти упав духом.","Богобоязкість твоя чи не повинна бути твоєю надією, і непорочність путів твоїх — упованням твоїм?","Згадай же, чи гинув хто невинний, і де праведних викорінювали?","Як я бачив, ті, що орали нечестя і сіяли зло, пожинають його;","від подуву Божого гинуть і від духу гніву Його зникають.","Ревіння лева і голос того, хто рикає, умовкає, і зуби скимнів ламаються;","могутній лев гине без здобичі, і діти левиці розсіюються.","І ось, до мене таємно прийшло слово, і вухо моє прийняло щось від нього.","Серед міркувань про нічні видіння, коли сон находить на людей,","обійняв мене жах і трепет і потряс усі кістки мої.","І дух пройшов наді мною, дибом стало волосся на мені.","Він став, — але я не розпізнав вигляду його, — тільки обрис був перед очима моїми; тихе віяння, — і я чую голос:","чи людина праведніша за Бога? і чи людина чистіша за Творця свого?","Ось, Він і слугам Своїм не довіряє і в ангелах Своїх убачає недоліки:","тим більше — в тих, хто живе у храминах із суміші, основа яких порох, які знищуються швидше за міль.","Між ранком і вечором вони розпадаються; не побачиш, як вони зовсім зникнуть.","Чи не гинуть з ними і чесноти їхні? Вони вмирають, не досягнувши мудрости."],"x":{"1":"24.15.1|24.22.1","3":"75.12.12","4":"31.35.3","8":"24.15.35|25.7.15","9":"9.22.16|70.2.8","10":"25.57.7|44.2.12","13":"24.33.15","14":"37.10.8","17":"24.9.2|24.15.14|24.25.4","18":"24.15.15|57.2.4|61.1.6","19":"24.25.6|64.5.1","20":"25.36.2"}},{"v":["Взивай, якщо є той, що відповідає тобі. І до кого зі святих звернешся ти?","Так, дурня убиває гнівливість, і нерозумного губить роздратування.","Бачив я, як дурень вкорінюється, і негайно прокляв дім його.","Діти його далекі від щастя, їх будуть бити біля воріт, і не буде захисника.","Жниво його з’їсть голодний і з-за терну візьме його, і спраглі поглинуть майно його.","Так, не з пороху виходить горе, і не з землі виростає лихо;","але людина народжується на страждання, як іскри, щоб підніматися вгору.","Але я до Бога звернувся б, передав би справу мою Богу,","Який творить діла великі і недослідимі, дивні без міри,","дає дощ на лице землі і посилає води на лице полів;","принижених поставляє на висоту, і ті, що ремствують, підносяться на спасіння.","Він руйнує задуми підступних, і руки їхні не довершують намірів.","Він уловлює мудреців їхнім же лукавством, і рада хитрих стає марною:","вдень вони зустрічають темряву й опівдні ходять навпомацки, як уночі.","Він спасає бідного від меча, від уст їх і від руки сильного.","І є нещасному надія, і неправда закриває вуста свої.","Блаженна людина, яку напоумлює Бог, і тому покарання Вседержителя не відкидай,","бо Він завдає рани і Сам обв’язує їх; Він уражає, і Його ж руки лікують.","У шести лихах врятує тебе, і в сьомому не торкнеться тебе зло.","Під час голоду визволить тебе від смерти, і на війні — від руки меча.","Від бича язика сховаєш себе і не убоїшся спустошення, коли воно прийде.","Спустошенню і голоду посмієшся і звірів землі не убоїшся,","бо з каменями польовими у тебе союз, і звірі польові у мирі з тобою.","І дізнаєшся, що намет твій у безпеці, і будеш дивитися за домом твоїм, і не згрішиш.","І побачиш, що сім’я твоє численне, і паростки твої, як трава на землі.","Увійдеш у гріб у зрілості, як укладаються снопи пшениці у свій час.","Ось, що ми пізнали; так воно і є; вислухай це і зауваж для себе."],"x":{"3":"25.36.35","7":"24.14.1","9":"24.9.10|25.71.18","10":"24.36.27|25.146.8","13":"63.3.19-20","14":"4.28.29","17":"26.3.11|55.1.12|75.12.5|76.3.19","18":"4.32.39","19":"25.90.10|31.43.2","20":"25.32.19","21":"25.54.22|26.26.22","23":"25.90.12|31.11.6"}},{"v":["І відповів Іов і сказав:","о, якби правильно були зважені волання мої, і разом з ними поклали на терези страждання моє!","Воно, напевно, перетягнуло б пісок морів! Від того слова мої несамовиті.","Бо стріли Вседержителя у мені; отрута їх п’є дух мій; жахи Божі ополчилися проти мене.","Чи реве дикий осел на траві? чи мичить бик біля місива свого?","Чи їдять несмачне без соли, і чи є смак в яєчному білку?","До чого не хотіла торкнутися душа моя, те складає огидну їжу мою.","О, коли б збулося бажання моє й уповання моє виконав Бог!","О, якби благоволив Бог розтрощити мене, простяг руку Свою й уразив мене!","Це було б ще відрадою мені, і я кріпився б у моїй нещадній хворобі, бо я не відмовився від слів Святого.","Що за сила у мене, щоб мати надію мені? і який кінець, щоб продовжити мені життя моє?","Чи твердість каменів — твердість моя? і чи мідь — плоть моя?","Чи є в мені допомога для мене, і чи є для мене яка опора?","До страдника повинне бути співчуття від друга його, якщо тільки він не покинув страху до Вседержителя.","Але брати мої невірні, як потік, як швидкоплинні струмки,","які чорні від льоду і в яких ховається сніг.","Коли стає тепло, вони зменшуються, а під час спеки зникають з місць своїх.","Вони змінюють напрямок шляхів своїх, заходять у пустелю і губляться:","дивляться на них дороги фемайські, сподіваються на них шляхи савейські,","але залишаються посоромленими у своїй надії; приходять туди і від сорому червоніють.","Так і ви тепер ніщо: побачили страшне і злякалися.","Чи говорив я: дайте мені, або від достатку вашого заплатіть за мене;","і визволіть мене від руки ворога, і від руки мучителів викупіть мене?","Навчіть мене, і я замовкну; покажіть, у чому я погрішив.","Які сильні слова правди! Але що доводять викриття ваші?","Ви придумуєте слова для викриття? На вітер пускаєте слова ваші.","Ви нападаєте на сироту і риєте яму другові вашому.","Але прошу вас, гляньте на мене; чи буду я говорити неправду перед лицем вашим?","Перегляньте, чи є неправда? переглянете, — правда моя.","Чи є на язику моєму неправда? Невже гортань моя не може розрізнити гіркоти?"],"x":{"3":"26.27.3","4":"4.32.23|25.37.3","9":"24.7.16|24.13.21","12":"63.10.13","15":"24.19.13|25.87.19","26":"24.16.6"}},{"v":["Чи не визначено людині час на землі, і дні її чи не такі самі, як і дні найманця?","Як раб жадає тіні, і як найманець чекає закінчення роботи своєї,","так я одержав у наділ місяці суєтні, і ночі гіркі відраховані мені.","Коли лягаю, то говорю: «колись встану?», а вечір триває, і я перевертаюся досита до самого світанку.","Тіло моє одягнене червою і запорошеними струпами; шкіра моя тріскається і гноїться.","Дні мої біжать скоріше за човника і закінчуються без надії.","Згадай, що життя моє подув, що око моє не повернеться, щоб бачити добре.","Не побачить мене око того, хто бачив мене; очі Твої на мене, — і немає мене.","Рідіє хмара й зникає; так той, хто зійшов у пекло, не вийде,","не повернеться більше у дім свій, і місце його вже не буде знати його.","Не буду ж я стримувати вуст моїх; буду говорити у пригніченні духу мого; буду скаржитися в печалі душі моєї.","Хіба я море або морське чудовисько, що Ти поставив наді мною сторожу?","Коли подумаю: втішить мене постіль моя, забере горе моє ложе моє,","ти страшиш мене снами і видіннями лякаєш мене;","і душа моя бажає краще припинення дихання, краще смерти, ніж збереження кісток моїх.","Огидним стало для мене життя. Не вічно жити мені. Відступи від мене, тому що дні мої суєта.","Що таке людина, що Ти так цінуєш її і звертаєш на неї увагу Твою,","відвідуєш її кожного ранку, кожну мить випробовуєш її?","Доки ж Ти не залишиш, доки не відійдеш від мене, доки не даси мені проковтнути слину мою?","Якщо я згрішив, то що я зроблю Тобі, страж людей! Навіщо Ти поставив мене супротивником Собі, так що я став самому собі за тягар?","І чому б не простити мені гріха і не зняти з мене беззаконня мого? бо, ось, я ляжу в порох; завтра шукатимеш мене, і мене немає."],"x":{"1":"24.14.6","4":"4.28.67","5":"24.2.7","6":"24.8.9|25.89.6|31.38.12","8":"25.38.14","9":"29.2.1","17":"25.8.5","20":"24.9.29"}},{"v":["І відповів Вилдад савхеянин і сказав:","чи довго ти будеш говорити так? — слова? вуст твоїх бурхливий вітер!","Невже Бог спотворює суд, і Вседержитель перетворює правду?","Якщо сини твої згрішили перед Ним, то Він і віддав їх у руку беззаконня їхнього.","Якщо ж ти знайдеш Бога і помолишся Вседержителю,","і якщо ти чистий і правий, то Він нині ж встане над тобою й умиротворить оселю правди твоєї.","І якщо спочатку в тебе було мало, то згодом буде дуже багато.","Бо запитай у минулих родів і вникни у спостереження батьків їх;","а ми — вчорашні і нічого не знаємо, тому що наші дні на землі тінь.","Ось, вони навчать тебе, скажуть тобі і від серця свого промовлять слова:","чи піднімається очерет без вологи? чи росте очерет без води?","Ще він у свіжості своїй і не зрізаний, а раніше всякої трави засихає.","Такі путі всіх, хто забуває Бога, і надія лицеміра загине;","уповання його підрізане, і впевненість його — дім павука.","Обіпреться об дім свій і не встоїть; схопиться за нього і не утримається.","Він зеленіє перед сонцем, за сад простягаються гілки його;","у купу каміння вплітається коріння його, між камінням врізується.","Але коли вирвуть його з місця його, воно відмовиться від нього: «я не бачило тебе!»","Ось радість шляху його! а із землі виростають інші.","Бачиш, Бог не відкидає непорочного і не підтримує руки? лиходіїв.","Він ще наповнить сміхом вуста твої і губи твої радісним вигуком.","Ненависники твої вдягнуться в сором, і намету нечестивих не стане."],"x":{"1":"24.18.1|24.25.1","3":"4.32.4|13.19.7|37.9.14","5":"24.22.23","7":"24.42.10","8":"4.4.32","9":"24.14.2|25.143.4","12":"25.128.6|32.17.6","13":"25.111.10|26.10.28","20":"25.36.18"}},{"v":["І відповів Іов і сказав:","правда! знаю, що так; але як виправдається людина перед Богом?","Якщо захоче вступити в суперечку з Ним, то не відповість Йому на жодне з тисячі.","Премудрий серцем і могутній силою; хто повставав проти Нього і залишався у спокої?","Він пересуває гори, і не впізнають їх: Він перетворює їх у гніві Своєму;","зрушує землю з місця її, і стовпи її тремтять;","скаже сонцю, — і не зійде, і на зірки накладає печатку.","Він один розпростирає небеса і ходить по висотах моря;","створив Ас, Кесиль і Хима* і тайники півдня;","робить велике, недослідиме і дивовижне без міри!","Ось, Він пройде переді мною, і не побачу Його; пронесеться, і не помічу Його.","Візьме, і хто заборонить Йому? хто скаже Йому: що Ти робиш?","Бог не відверне гніву Свого; перед Ним упадуть поборники гордині.","Тим більше чи можу я відповідати Йому і вишукувати собі слова перед Ним?","Хоч би я і правий був, але не буду відповідати, а буду благати Суддю мого.","Якби я воззвав, і Він відповів мені, — я не повірив би, що голос мій почув Той,","Хто у вихорі вражає мене і примножує невинно мої рани,","не дає мені перевести дух, але пересичує мене гіркотою.","Якщо діяти силою, то Він могутній; якщо судом, хто зведе мене з Ним?","Якщо я буду виправдовуватися, то мої ж вуста звинуватять мене; якщо я невинний, то Він визнає мене винним.","Невинний я; не хочу знати душі моєї, зневажаю життя моє.","Все одно; тому я сказав, що Він губить і непорочного і винного.","Якщо цього вражає Він бичем раптово, то над катуванням невинних сміється.","Земля віддана в руки нечестивих; обличчя суддів її Він закриває. Якщо не Він, то хто ж?","Дні мої швидші за гінця, — біжать, не бачать добра,","несуться, як легкі човни, як орел рине на здобичу.","Якщо сказати мені: забуду я скарги мої, відкину похмурий вигляд свій і підбадьорюся;","то тремчу від усіх страждань моїх, знаючи, що Ти не оголосиш мене невинним.","Якщо ж я винен, то для чого даремно томлюся?","Хоч би я обмився і сніговою водою і зовсім очистив руки мої,","то і тоді Ти зануриш мене у бруд, і буде гидувати мною одяг мій.","Тому що Він не людина, як я, щоб я міг відповідати Йому і йти разом з Ним на суд!","Немає між нами посередника, який поклав би руку свою на обох нас.","Нехай відведе Він від мене жезл Свій, і страх Його нехай не жахає мене, —","і тоді я буду говорити і не убоюся Його, бо я не такий сам у собі."],"x":{"2":"24.4.17","4":"24.37.23","5":"32.51.25|50.17.20","7":"5.10.13|11.20.11","8":"32.51.15","10":"24.5.9","12":"31.10.15|31.14.27","13":"44.1.6","15":"24.10.7","21":"63.4.4","22":"24.34.9","25":"24.7.7|25.89.10","26":"29.5.10","29":"24.7.20","30":"32.2.22","32":"27.6.10|32.49.19","34":"25.88.33","35":"63.4.4"},"n":{"9":["Сузір’я, що відповідають нинішнім назвам: Ведмедиця, Оріон і Плеяди."]}},{"v":["Обридло душі моїй життя моє; віддамся суму моєму; буду говорити в скорботі душі моєї.","Скажу Богу: не звинувачуй мене; оголоси мені, за що Ти зі мною борешся?","Чи добре для Тебе, що Ти пригнічуєш, що зневажаєш діла рук Твоїх, а на раду нечестивих посилаєш світло?","Хіба у Тебе плотські очі, і Ти дивишся, як дивиться людина?","Хіба дні Твої, як дні людини, або літа Твої, як дні чоловіка,","чому Ти шукаєш пороку в мені і допитуєшся гріха в мені,","хоча знаєш, що я не беззаконник, і що нема кому визволити мене від руки Твоєї?","Твої руки трудилися наді мною й створили всього мене цілком, — і Ти губиш мене?","Згадай, що Ти, як глину, обробив мене, і в порох повертаєш мене?","Чи не Ти вилив мене, як молоко, і, як сир, згустив мене,","шкірою і плоттю одяг мене, кістками і жилами скріпив мене,","життя і милість дарував мені, і піклування Твоє зберігало дух мій?","Але і те приховував Ти в серці Своєму, — знаю, що це було в Тебе, —","бо якщо я згрішу, Ти помітиш і не залишиш гріха мого без покарання.","Якщо я винен, горе мені! якщо і правий, то не насмілюся підняти голови моєї. Я пересичений приниженням; глянь на страждання моє:","воно збільшується. Ти женешся за мною, як лев, і знову нападаєш на мене і дивним являєшся в мені.","Виводиш нових свідків Твоїх проти мене; підсилюєш гнів Твій на мене; і біди, одні за іншими, ополчаються проти мене.","І навіщо Ти вивів мене з утроби? нехай би я помер, коли ще нічиє око не бачило мене;","нехай би я, як той, що не був, з утроби перенесений був у гріб!","Чи не короткі дні мої? Залиш, відступи від мене, щоб я трохи підбадьорився,","раніше ніж відійду, — і вже не повернуся, — у країну темряви і сіні смертної,","у країну мороку, який є морок тіні смертної, де немає упорядкування, де темно, як сама темрява."],"x":{"2":"24.34.10","4":"8.16.7","5":"25.101.28","7":"24.9.15|18.13.2","8":"25.118.73","9":"0.2.7|0.3.19","11":"22.7.11","14":"25.89.8","15":"24.35.2","17":"24.19.12","18":"24.3.11|32.20.14","20":"25.38.14","21":"24.16.22","22":"31.5.14"}},{"v":["І відповів Софар наамитянин і сказав:","хіба на безліч слів не можна дати відповіді, і хіба людина багатослівна права?","Марнослів’я твоє чи змусить мовчати мужів, щоб ти глумився, і нікому було присоромити тебе?","Ти сказав: судження моє вірне, і чистий я в очах Твоїх.","Але якби Бог заговорив і відкрив уста Свої до тебе","і відкрив тобі таємниці премудрости, що тобі вдвічі більше належало б понести! Отже, знай, що Бог для тебе деякі з беззаконь твоїх піддав забуттю.","Чи можеш ти дослідженням знайти Бога? Чи можеш зовсім пізнати Вседержителя?","Він вище небес, — що ти можеш зробити? глибше пекла, — що можеш дізнатися?","Довша за землю міра Його і ширша за море.","Якщо Він пройде й закує кого в кайдани і представить на суд, то хто відхилить Його?","Бо Він знає людей неправдивих і бачить беззаконня, і чи залишить його без уваги?","Але пустий чоловік мудрує, хоч людина народжується подібно до дикого осляти.","Якщо ти управиш серце твоє і простягнеш до Нього руки твої,","і якщо є порок у руці твоїй, а ти відкинеш його і не даси беззаконню жити в наметах твоїх,","то піднімеш незаплямоване лице твоє і будеш твердим і не будеш боятися.","Тоді забудеш горе: як про воду, яка протекла, будеш згадувати про нього.","І ясніше за полудень піде життя твоє; просвітлієш, як ранок.","І будеш спокійний, тому що є надія; ти огороджений, і можеш спати безпечно.","Будеш лежати, і не буде того, що страшить, і багато хто буде підлещуватися до тебе.","А очі беззаконних витечуть, і притулок їхній пропаде, і надія їхня зникне."],"x":{"1":"24.2.11|24.20.1","2":"26.10.14","6":"25.50.8","7":"62.11.33|63.2.11","8":"25.138.8|32.23.24","11":"25.93.9","14":"31.1.16-18","15":"58.3.21","16":"32.12.11","17":"25.36.6|31.58.8","19":"2.26.5","20":"24.8.13|24.14.19"}},{"v":["І відповів Іов і сказав:","дійсно, тільки ви люди, і з вами помре мудрість!","І у мене є серце, як у вас; не нижчий я за вас; і хто не знає того ж?","Посміховищем став я для друга свого, я, що взивав до Бога, і якому Він відповідав, посміховиськом — чоловік праведний, непорочний.","Так знехтуваний за думками того, хто сидить у спокої, смолоскип, приготований для тих, що спотикаються ногами.","Спокійні намети у грабіжників і безпечні у тих, хто прогнівляє Бога, які ніби Бога носять у руках своїх.","І справді: запитай у худоби, і навчить тебе, у птаха небесного, і сповістить тебе;","або поговори з землею, і наставить тебе, і скажуть тобі риби морські.","Хто у всьому цьому не узнає, що рука Господа створила це?","В Його руці душа всього, що живе, і дух усякої людської плоті.","Чи не вухо розрізняє слова, і чи не язик розпізнає смак їжі?","У старцях — мудрість, і у довголітніх — розум.","У Нього премудрість і сила; Його рада і розум.","Що Він зруйнує, те не побудується; кого Він ув’язнить, той не звільниться.","Зупинить води, і все висохне; пустить їх, і перетворять землю.","У Нього могутність і премудрість, перед Ним той, хто помиляється і вводить в оману.","Він приводить радників до необміркованости і суддів робить нерозумними.","Він позбавляє перев’язів царів і поясом обв’язує стегна їхні;","князів позбавляє достоїнства і долає хоробрих;","віднімає язик у красномовців і старців позбавляє сенсу;","покриває соромом знаменитих і силу могутніх ослаблює;","відкриває глибоке із середовища пітьми і виводить на світло тінь смертну;","примножує народи і знищує їх; розсіває народи і збирає їх;","віднімає розум у глав народу землі і залишає їх блукати в пустелі, де немає шляхів:","навпомацки ходять вони у темряві без світла і тиняються, як п’яні."],"x":{"4":"24.17.6|29.5.3","6":"24.21.7|25.72.3|32.12.1","9":"26.16.4|40.3.6","10":"54.17.28","11":"24.34.3","12":"24.15.10","13":"29.7.25","14":"31.22.22|76.3.7","15":"0.7.11","17":"31.29.14","20":"70.2.11","21":"31.28.15","24":"25.75.13","25":"31.29.9|31.59.10"}},{"v":["Ось, усе це бачило око моє, чуло вухо моє і помітило для себе.","Скільки знаєте ви, знаю і я: не нижчий я за вас.","Але я до Вседержителя хотів би говорити і бажав би змагатися з Богом.","А ви плітники неправди; усі ви марні лікарі.","О, якби ви тільки мовчали! це було б поставлено вам за мудрість.","Вислухайте ж міркування мої і вникніть у заперечення вуст моїх.","Чи належало вам заради Бога говорити неправду і для Нього говорити лжу?","Чи належало вам бути упередженими до Нього і за Бога так сперечатися?","Чи добре буде, коли Він випробує вас? Чи обманете Його, як обманюють людину?","Суворо покарає Він вас, хоч ви і приховано лицемірите.","Невже велич Його не страшить вас, і страх Його не нападає на вас?","Нагадування ваші подібні до попелу; опори ваші — оплоти глиняні.","Замовкніть переді мною, і я буду говорити, що не осягло б мене.","Для чого мені терзати тіло моє зубами моїми і душу мою вкладати в руку мою?","Ось, Він убиває мене, але я буду сподіватися; я бажав би тільки відстояти путі мої перед лицем Його!","І це вже на виправдання мені, тому що лицемір не піде перед лице Його!","Вислухайте уважно слово моє і пояснення моє вухами вашими.","Ось, я завів судову справу: знаю, що буду правий.","Хто у змозі заперечити мені? Бо я скоро замовкну і спущу дух.","Двох тільки речей не роби зі мною, і тоді я не буду ховатися від лиця Твого:","відніми від мене руку Твою, і жах Твій нехай не потрясає мене.","Тоді клич, і я буду відповідати, або буду говорити я, а Ти відповідай мені.","Скільки в мене пороків і гріхів? покажи мені беззаконня моє і гріх мій.","Для чого ховаєш лице Твоє і вважаєш мене ворогом Твоїм?","Чи не зірваний листок Ти розтрощуєш і чи не суху соломину переслідуєш?","Бо Ти пишеш на мене гірке і ставиш у провину мені гріхи юности моєї,","і ставиш у колоду ноги мої і підстерігаєш усі шляхи мої, — женешся слідами ніг моїх.","А він, як гниле, розпадається, як одяг, з’їдений міллю."],"x":{"2":"24.12.3|24.15.9","4":"24.16.2","5":"26.17.28","10":"4.10.17","16":"50.7.23","21":"24.6.9","22":"24.38.3","24":"25.43.25|24.19.11|24.33.10","26":"25.24.7","28":"24.4.19|31.51.8"}},{"v":["Людина, народжена жінкою, короткочасна і пересичена печалями:","як квітка, вона виростає й опадає; тікає, як тінь, і не зупиняється.","І на неї-то Ти відкриваєш очі Твої, і мене ведеш на суд з Тобою?","Хто народиться чистим від нечистого? Жоден.","Якщо дні йому визначені, і число місяців його в Тебе, якщо Ти поклав йому межу, якої він не перейде,","то ухилися від нього: нехай він відпочине, доки не закінчить, як найманець, дня свого.","Для дерева є надія, що воно, якщо і буде зрубане, знову оживе, і паростки від нього виходити не перестануть:","якщо і застарів у землі корінь його, і пеньок його завмер у поросі,","але, лиш відчуло воду, воно дає паростки і пускає гілки, ніби знову посаджене.","А людина вмирає і розпадається; відійшла, і де вона?","Витікає вода з озера, і ріка вичерпується і висихає:","так людина ляже і не встане; до закінчення неба вона не пробудиться і не встане від сну свого.","О, якби Ти в пеклі сховав мене і приховував мене, доки пройде гнів Твій, поклав мені термін і потім згадав про мене!","Коли помре людина, то чи буде вона знову жити? В усі дні визначеного мені часу я очікував би, поки прийде мені зміна.","Покликав би Ти, і я дав би Тобі відповідь, і Ти явив би благовоління творінню рук Твоїх;","бо тоді Ти підраховував би кроки мої і не підстерігав би гріха мого;","у сувої було б запечатане беззаконня моє, і Ти закрив би провину мою.","Але гора, падаючи, руйнується, і скеля сходить з місця свого;","вода стирає камені; паводок її змиває земний порох: так і надію людини Ти знищуєш.","Пригнічуєш її до кінця, і вона відходить; змінюєш їй лице і відсилаєш її.","Чи в пошані діти її — вона не знає, чи принижені — вона не відає;","але плоть її на ній болить, і душа її в ній страждає."],"x":{"1":"30.18.8","2":"24.8.9|25.143.4","4":"25.50.7|31.64.6","6":"24.7.1-2","12":"24.19.25|37.12.2","15":"24.10.8","16":"24.31.4|25.138.2","17":"38.13.12|36.18.22","21":"27.2.19"}},{"v":["І відповів Елифаз феманитянин і сказав:","чи стане мудрий відповідати знанням пустим і наповнювати утробу свою вітром палючим,","виправдовуватися словами марними і промовою, яка не має ніякої сили?","Так ти відклав і страх і за ніщо вважаєш слова до Бога.","Нечестя твоє так налаштувало вуста твої, і ти обрав язик лукавих.","Тебе звинувачують уста твої, а не я, і твій язик говорить проти тебе.","Хіба ти першою людиною народився і раніше пагорбів створений?","Хіба раду Божу ти чув і залучив до себе премудрість?","Що знаєш ти, чого б не знали ми? що розумієш ти, чого не було б і у нас?","І сивоволосий і старець є між нами, що днями перевищує батька твого.","Хіба малі для тебе утішення Божі? І це невідомо тобі?","До чого закликає тебе серце твоє, і чому так гордо дивишся?","Навіщо спрямовуєш проти Бога дух твій і вустами твоїми промовляєш такі слова?","Що таке людина, щоб бути їй чистою, і щоб народженому жінкою бути праведним?","Ось, Він і святим Своїм не довіряє, і небеса нечисті в очах Його:","тим більше нечиста і розтлінна людина, яка п’є беззаконня, як воду.","Я буду говорити тобі, слухай мене; я розповім тобі, що бачив,","що чули мудрі і не приховали того, що почули від батьків своїх,","яким одним віддана була земля, і серед яких чужий не ходив.","Нечестивий мучить себе в усі дні свої, і число років закрите від гнобителя;","звук жахів у вухах його; під час миру іде на нього згубник.","Він не сподівається врятуватися від темряви; бачить перед собою меч.","Він поневіряється за шматком хліба всюди; знає, що вже готовий, в руках у нього день пітьми.","Страшать його нестатки і пригнічення; долають його, як цар, який приготувався до битви,","за те, що він простягав проти Бога руку свою і противився Вседержителю,","виступав проти Нього з гордою шиєю, під товстими щитами своїми;","тому що він покрив лице своє жиром своїм і обклав жиром стегна свої.","І він оселяється в містах зруйнованих, у домах, у яких не живуть, які приречені на руїни.","Не стане він багатим, і не вціліє майно його, і не розповсюдиться по землі надбання його.","Не втече від пітьми; паростки його висушить полум’я і подихом вуст своїх втягне його.","Нехай не довіряє суєті заблудлий, тому що суєта буде і відплатою йому.","Не у свій день він помре, і віття його не буде зеленіти.","Скине він, як виноградна лоза, недостиглу ягоду свою і, як олива, стряхне цвіт свій.","Так стане порожнім дім нечестивого, і вогонь пожере намети хабарництва.","Він зачав зло і породив неправду, й утроба його готує оману."],"x":{"1":"24.4.1|24.22.1","6":"50.12.37","7":"26.8.25","8":"31.40.13|32.23.18","9":"24.13.2","14":"0.6.5|10.8.46|13.6.36","15":"24.4.18","16":"68.2.13","20":"26.28.1|31.48.22","21":"2.26.36","23":"24.18.11|25.108.10","25":"2.26.21","27":"4.32.15-16|25.16.10|25.118.70","30":"24.4.9|70.2.8","32":"24.22.16|25.54.24|25.72.19|27.7.17","34":"31.9.19","35":"25.7.15|31.59.4"}},{"v":["І відповів Іов і сказав:","чув я багато такого; жалюгідні утішителі всі ви!","Чи буде кінець легковажним словам? і що спонукало тебе так відповідати?","І я міг би так само говорити, як ви, якби душа ваша була на місці душі моєї; ополчався б на вас словами і кивав би на вас головою моєю;","підкріплював би вас язиком моїм і рухом губ утішав би.","Чи говорю я, не стихає скорбота моя; чи перестаю, що відходить від мене?","Але нині Він виснажив мене. Ти зруйнував усю родину мою.","Ти покрив мене зморшками як свідчення проти мене; повстає на мене виснаженість моя, у лице докоряє мені.","Гнів Його терзає і ворогує проти мене, скрегоче на мене зубами своїми; ворог мій гострить на мене очі свої.","Розкрили на мене пащу свою; ганьблять і б’ють мене по щоках: усі змовилися проти мене.","Віддав мене Бог беззаконнику і у руки нечестивих кинув мене.","Я був спокійним, але Він потряс мене; взяв мене за шию і побив мене і поставив мене мішенню для Себе.","Оточили мене стрільці Його; Він розсікає нутрощі мої і не щадить, пролив на землю жовч мою,","пробиває в мені пролам за проламом, біжить на мене, як ратоборець.","Веретище зшив я на шкіру мою й у порох поклав голову мою.","Обличчя моє почервоніло від плачу, і на повіках моїх тінь смерти,","попри все те, що немає вкраденого в руках моїх, і молитва моя чиста.","Земле! не закрий моєї крови, і нехай не буде місця воланню моєму.","І нині ось на небесах Свідок мій, і Заступник мій у вишніх!","Багатомовні друзі мої! До Бога плачуть очі мої.","О, якби чоловік міг змагатися з Богом, як син людський із ближнім своїм!","Бо літам моїм приходить кінець, і я відходжу в путь безповоротну."],"x":{"2":"24.21.34","7":"24.10.17","12":"25.101.14|4.32.23","16":"24.17.7|25.6.7-8","17":"71.2.8","22":"5.23.14|24.7.21|24.10.21"}},{"v":["Дихання моє ослабло; дні мої вгасають; гроби переді мною.","Якби не глузування їх, то і серед спорів їх око моє перебувало б спокійним.","Заступися, поручися Сам за мене перед Собою! інакше хто поручиться за мене?","Бо Ти закрив серце їх від розуміння, і тому не даси торжествувати їм.","Хто прирікає друзів своїх на здобич, у дітей того очі витечуть.","Він поставив мене притчею для народу і посміховищем для нього.","Помутніли від горя очі мої, і всі члени мої, як тінь.","Здивуються від цього праведні, і невинний обуриться на лицеміра.","Але праведник буде міцно триматися путі своєї, і чистий руками буде більше і більше утверджуватися.","Виступайте, всі ви, і підійдіть; не знайду я мудрого між вами.","Дні мої минули; думи мої — надбання серця мого — розбиті.","А вони ніч хочуть перетворити на день, світло наблизити до лиця пітьми.","Якби я й очікувати став, то пекло — дім мій; у пітьмі постелю я постіль мою;","гробу скажу: ти батько мій, черві: ти мати моя і сестра моя.","Де ж після цього надія моя? і очікуване мною хто побачить?","У пекло зійде вона і буде спочивати зі мною у поросі."],"x":{"4":"50.11.25","5":"24.11.20","6":"24.12.4|24.30.9|36.33.32","7":"25.6.8","14":"30.10.13"}},{"v":["І відповів Вилдад савхеянин і сказав:","коли ж покладете ви кінець таким словам? обміркуйте, і потім будемо говорити.","Навіщо вважатися нам за тварин і бути приниженими у власних очах ваших?","О ти, що роздираєш душу твою у гніві твоєму! Невже для тебе — спустіти землі, і скелі зрушити з місця свого?","Так, світло в беззаконного погасне, і не залишиться іскри від вогню його.","Померкне світло в наметі його, і світильник його погасне над ним.","Скоротяться кроки могутности його, і подолає його власний намір його,","бо він потрапить у сіті свої ногами і по тенетах ходити буде.","Петля зачепить за ногу його, і грабіжник уловить його.","Потай розкладені по землі сильці для нього і пастки на дорозі.","З усіх боків будуть страшити його жахи і примусять його кидатися туди і сюди.","Виснажиться від голоду сила його, і загибель готова, збоку в нього.","З’їсть члени тіла його, з’їсть члени його первісток смерти.","Вигнана буде з намету його надія його, і це зведе його до царя жахів.","Оселяться в наметі його, тому що він уже не його; житло його посипане буде сіркою.","Знизу підсохнуть корені його, і зверху зів’януть гілки його.","Пам’ять про нього зникне з землі, й імені його не буде на площі.","Виженуть його зі світла в темряву і зітруть його з лиця землі.","Ні сина його, ні онука не буде в народі його, і нікого не залишиться в оселях його.","Про день його жахнуться нащадки, і сучасники будуть обійняті тремтінням.","Такі оселі беззаконного, і таке місце того, хто не знає Бога."],"x":{"1":"24.8.1|24.25.1","5":"24.21.17","6":"24.29.3|26.13.9","7":"20.7.9","9":"24.5.5","11":"24.27.20","14":"24.11.20","15":"0.19.24","16":"40.2.9","17":"26.2.22","19":"25.36.28|29.3.16","20":"25.36.13","21":"24.20.29"}},{"v":["І відповів Іов і сказав:","доки будете мучити душу мою і мучити мене словами?","Ось, уже разів десять ви соромили мене і не соромитеся гнітити мене.","Якщо я і дійсно згрішив, то провина моя при мені залишається.","Якщо ж ви хочете величатися наді мною і дорікати мене ганьбою моєю,","то знайте, що Бог відкинув мене й обклав мене Своєю сіткою.","Ось, я кричу; образа! і ніхто не слухає; волаю, і немає суду.","Він перекрив мені дорогу, і не можу пройти, і на шляхи мої поклав темряву.","Стягнув з мене славу мою і зняв вінець з голови моєї.","Зовсім зруйнував мене, і я відходжу; і, як дерево, Він вивергнув надію мою.","Запалав на мене гнівом Своїм і вважає мене між ворогами Своїми.","Полки Його прийшли разом і спрямували шлях свій до мене і розташувалися навколо намету мого.","Братів моїх Він віддалив від мене, і ті, що знають мене, цураються мене.","Покинули мене близькі мої, і знайомі мої забули мене.","Прибулі у домі моєму і служниці мої чужим вважають мене; стороннім став я в очах їхніх.","Кличу слугу мого, і він не відгукується; вустами моїми я повинен благати його.","Дихання моє стало огидним дружині моїй, і я повинен благати її заради дітей утроби моєї.","Навіть малі діти зневажають мене: піднімаюся, і вони знущаються з мене.","Гребують мною всі наперсники мої, і ті, яких я любив, повернулися проти мене.","Кістки мої прилипли до шкіри моєї і плоті моєї, і я залишився тільки зі шкірою біля зубів моїх.","Помилуйте мене, помилуйте мене ви, друзі мої, бо рука Божа торкнулася мене.","Навіщо і ви переслідуєте мене, як Бог, і плоттю моєю не можете насититися?","О, якби записані були слова мої! Якби накреслені були вони у книзі","різцем залізним з оловом, — на вічний час на камені вирізані були!","А я знаю, Відкупитель мій живий, і Він в останній день воскресить з пороху цю мою шкіру, що розпадається,","і я у плоті моїй побачу Бога.","Я побачу Його сам; мої очі, не очі іншого, побачать Його. Тане серце моє в грудях моїх!","Вам належало б сказати: навіщо ми переслідуємо його? Начебто корінь зла знайшли в мені.","Побійтесь меча, тому що меч є месником за неправди, і знайте, що є суд."],"x":{"4":"62.14.12-13|65.6.5","6":"38.7.12","7":"25.68.4|32.20.8","8":"33.3.7:9","11":"24.33.10","12":"24.25.3","13":"25.30.12","17":"24.2.9","25":"65.3.14|76.5.9|36.37.3|22.7.11|53.11.25","27":"53.8.56|45.2.4"}},{"v":["І відповів Софар наамитянин і сказав:","розмірковування мої спонукують мене відповідати, і я поспішаю висловити їх.","Докір, ганебний для мене, вислухав я, і дух розуміння мого відповість за мене.","Хіба не знаєш ти, що від віку, — з того часу, як поставлена людина на землі, —","веселощі беззаконних короткочасні, і радість лицеміра миттєва?","Хоч би зросла до небес велич його, і голова його торкалася хмар, —","як гній його, навіки пропадає він; ті, що бачили його, скажуть: де він?","Як сон, відлетить, і не знайдуть його; і, як нічне видіння, зникне.","Око, що бачило його, більше не побачить його, і вже не дивитиметься на нього місце його.","Сини його будуть запобігати перед жебраками, і руки його повернуть вкрадене ним.","Кістки його наповнені гріхами юности його, і з ним ляжуть вони у порох.","Якщо солодке в роті його зло, і він таїть його під язиком своїм,","береже і не кидає його, а тримає його у вустах своїх,","то ця їжа його в утробі його перетвориться на жовч аспидів усередині його.","Майно, яке він ковтав, виблює: Бог вивергне його із утроби його.","Зміїну отруту він ссе; умертвить його язик єхидни.","Не бачити йому струмків, рік, що течуть медом і молоком!","Нажите трудом поверне, не проковтне; за міркою майна його буде і розплата його, а він не порадіє.","Бо він гнітив, відсилав бідних; захоплював доми, яких не будував;","не знав ситости в утробі своїй і у жадобі своїй не щадив нічого.","Нічого не спаслося від обжерливости його, зате не встоїть щастя його.","У повноті достатку буде тісно йому; всяка рука скривдженого підніметься на нього.","Коли буде чим наповнити утробу його, Він пошле на нього лють гніву Свого й буде дощити на нього хвороби в плоті його.","Чи втече він від зброї залізної, — проколе його лук мідний;","стане виймати стрілу, — і вона вийде з тіла, вийде, блискаючи крізь жовч його; жахи смерти найдуть на нього!","Все похмуре сховано всередині його; буде пожирати його вогонь, який ніхто не роздмухує; зло осягне і те, що залишилося в наметі його.","Небо відкриє беззаконня його, і земля повстане проти нього.","Зникне надбання дому його; усе розпливеться в день гніву Його.","Ось доля людини беззаконної і спадщина, визначена їй Вседержителем!"],"x":{"1":"24.11.1","5":"75.11.25","7":"69.5.3|25.36.36","8":"25.72.19|31.29.7","9":"25.36.10|25.102.16","10":"24.21.19|24.27.14","12":"25.54.22","18":"32.12.13","19":"31.5.8","20":"26.10.2|26.11.4|30.5.10|36.7.19","23":"3.11.33","24":"31.24.18|32.48.44","25":"25.7.13|36.21.10","26":"4.32.22|32.15.14|32.17.4","29":"24.18.21|24.27.13"}},{"v":["І відповів Іов і сказав;","вислухайте уважно слова мої, і це буде мені утіхою від вас.","Потерпіть мене, і я буду говорити; а після того, як скажу, насміхайтеся.","Хіба до людини слова мої? як же мені і не бути слабкодухим?","Подивіться на мене і вжахніться, і покладіть перст на вуста.","Лише тільки я згадаю, — здригаюсь, і тремтіння обіймає тіло моє.","Чому беззаконні живуть, досягають старости, та й силою міцні?","Діти їхні з ними перед лицем їх, і онуки їхні перед очима їх.","Доми їхні безпечні від страху, і немає жезла Божого на них.","Віл їх запліднює і не вивергає, корова їх зачинає і не викидає.","Як стадо, випускають вони малюків своїх, і діти їхні стрибають.","Викликують під голос тимпана і цитри і веселяться при звуках сопілки;","проводять дні свої у щасті і миттєво сходять у пекло.","А між тим вони говорять Богу: відійди від нас, ми не хочемо знати шляхів Твоїх!","Хто такий Вседержитель, щоб нам служити Йому? і яка користь прибігати до Нього?","Бачиш, щастя їх не від їхніх рук. — Рада нечестивих, будь далекою від мене!","Чи часто гасне світильник у беззаконних, і находить на них лихо, і Він дає їм у наділ страждання у гніві Своєму?","Вони повинні бути, як соломинка перед вітром і як полова, яку розносить вихор.","Скажеш: Бог береже для дітей його нещастя його. — Нехай віддасть Він йому самому, щоб він це знав.","Нехай його очі побачать нещастя його, і нехай він сам п’є від гніву Вседержителевого.","Бо яка йому турбота про дім свій після нього, коли число місяців його закінчиться?","Але чи Бога вчити мудрости, коли Він судить і небесних?","Один помирає в самій повноті сил своїх, зовсім спокійний і мирний;","нутрощі його повні жиру, і кістки його напоєні мозком.","А інший помирає з душею засмученою, не вкусивши добра.","І вони разом будуть лежати в поросі, і черва покриє їх.","Знаю я ваші думки і хитрощі, які ви проти мене сплітаєте.","Ви скажете: де дім князя, і де намет, у якому жили беззаконні?","Хіба ви не запитували у подорожніх і незнайомі з їх спостереженнями,","що у день загибелі пощаджений буває лиходій, у день гніву відводиться убік?","Хто представить йому перед лице путь його, і хто відплатить йому за те, що він робив?","Його проводжають до гробів і на його могилі ставлять варту.","Солодкі для нього брили долини, і за ним іде натовп людей, а тим, що йдуть перед ним, немає числа.","Як же ви хочете утішати мене пустим? У ваших відповідях залишається одна неправда."],"x":{"5":"43.7.16","7":"32.12.1|45.1.13","9":"25.72.4|25.143.12","12":"31.5.12|40.6.5-6","14":"24.22.17|32.2.20","15":"49.3.14","16":"24.22.18","17":"24.18.5-6|24.29.3|24.38.15","18":"25.1.4|31.29.5|38.13.3","21":"25.54.24|25.57.10","26":"24.17.14","30":"25.72.18-19|26.16.4","34":"24.16.2"}},{"v":["І відповів Елифаз феманитянин і сказав:","хіба може людина приносити користь Богу? Розумний приносить користь собі самому.","Яке задоволення Вседержителю від того, що ти праведний? І чи буде Йому вигода від того, що ти тримаєш путі твої у непорочності?","Невже Він, боячись тебе, вступить з тобою в змагання, піде судитися з тобою?","Певно, злоба твоя велика, і беззаконням твоїм немає кінця.","Певно, ти брав застави від братів твоїх ні за що і з напівголих знімав одяг.","Стомленому спрагою не подавав води напитися і голодному відмовляв у хлібі;","а людині сильній ти давав землю, і сановитий оселявся на ній.","Вдів ти відсилав ні з чим і сиріт залишав з порожніми руками.","За те навколо тебе петлі, і збурив тебе несподіваний жах,","або пітьма, в якій ти нічого не бачиш, і великі води покрили тебе.","Чи не вище небес Бог? подивися вгору на зірки, як вони високо!","І ти говориш: що знає Бог? чи може Він судити крізь морок?","Хмари — завіса Його, так що Він не бачить, а ходить тільки по небесному колу.","Невже ти тримаєшся путі древніх, якою йшли люди беззаконні,","які передчасно були винищені, коли вода розлилася під основу їхню?","Вони говорили Богу: відійди від нас! і що зробить їм Вседержитель?","А Він наповнював доми їхні добром. Але, рада нечестивих, будь далекою від мене!","Бачили праведники і раділи, і непорочний сміявся:","ворог наш знищений, а те, що залишилося після них, пожер вогонь.","Зблизься ж з Ним — і будеш спокійний; через це прийде до тебе добро.","Прийми з вуст Його закон і поклади слова Його в серце твоє.","Якщо ти звернешся до Вседержителя, то знову влаштуєшся, проженеш беззаконня від намету твого","і будеш вважати за порох блискучий метал, і за камені потоків — золото Офірське.","І буде Вседержитель твоїм золотом і блискучим сріблом у тебе,","бо тоді будеш радуватися за Вседержителя і піднімеш до Бога лице твоє.","Помолишся Йому, і Він почує тебе, і ти виконаєш обітниці твої.","Покладеш намір, і він здійсниться у тебе, і над путями твоїми буде сяяти світло.","Коли хто буде принижений, ти скажеш: піднесення! і Він спасе засмученого лицем,","визволить і невинного, і він спасеться чистотою рук твоїх."],"x":{"1":"24.4.1|24.15.1","3":"24.35.7","6":"36.18.7|31.58.7","7":"50.25.42","10":"9.22.6","11":"9.22.17","13":"24.24.15|25.93.7|31.29.15","15":"56.4.2","16":"24.15.32","18":"24.21.16","19":"25.106.42","20":"36.28.18","23":"24.8.5-6","27":"25.49.15|31.58.9|31.65.24","29":"26.29.23|52.18.14","30":"25.17.21"}},{"v":["І відповів Іов і сказав:","ще і нині гіркі слова мої: страждання мої важчі за стогнання моє.","О, якби я знав, де знайти Його, і міг підійти до престолу Його!","Я виклав би перед Ним справу мою і вуста мої наповнив би виправданнями;","спізнав би слова, якими Він відповість мені, і зрозумів би, що Він скаже мені.","Невже Він у повній могутності став би змагатися зі мною? О, ні! Нехай Він тільки звернув би увагу на мене.","Тоді праведник міг би змагатися з Ним, — і я назавжди одержав би свободу від Судді мого.","Але ось, я йду вперед — і нема Його, назад — і не знаходжу Його;","чи робить Він що на лівій стороні, я не бачу; чи ховається на правій, не вбачаю.","Але Він знає путь мою; нехай випробує мене, — вийду, як золото.","Нога моя твердо тримається стежок Його; путі Його я зберігав і не ухилявся.","Від заповіді вуст Його не відступав; слова вуст Його зберігав більше, ніж мої правила.","Але Він твердий; і хто відхилить Його? Він робить, чого хоче душа Його.","Так, Він виконає те, що належить мені, і подібного до цього багато у Нього.","Тому я тремчу перед лицем Його; розмірковую — і страшуся Його.","Бог розслабив серце моє, і Вседержитель налякав мене.","Чому я не був знищений раніше цієї темряви, і Він не приховав мороку від лиця мого!"],"x":{"10":"24.31.4|24.33.9","11":"25.118.51"}},{"v":["Чому не приховані від Вседержителя часи, і ті, що знають Його, не бачать днів Його?","Межі пересувають, викрадають стада і пасуть у себе.","У сиріт відбирають осла, у вдови беруть у заставу вола;","бідних зіштовхують з дороги, всі принижені землі примушені ховатися.","Ось вони, як дикі осли в пустелі, виходять на справу свою, встаючи рано на здобич; степ дає хліб для них і для дітей їхніх;","жнуть вони на полі не своєму і збирають виноград у нечестивця;","нагі ночують без покрова і без одягу на холоді;","мокнуть від гірських дощів і, не маючи притулку, тиснуться до скелі;","відривають від грудей сироту і з убогого беруть заставу;","змушують ходити нагими, без одягу, і голодних годують колоссям;","між стінами вичавлюють олію оливкову, топчуть у точилах і жадають.","У містах люди стогнуть, і душа тих, кого убивають, волає, і Бог не забороняє того.","Є з них вороги світла, не знають путі його і не ходять стежками його.","Зі світанком встає вбивця, умертвляє бідного й убогого, а вночі буває злодієм.","І око перелюбника чекає сутінків, говорячи: нічиє око не побачить мене, — і закриває лице.","У темряві підкопуються під доми, які вдень вони помітили для себе; не знають світла.","Бо для них ранок — смертна тінь, оскільки вони знайомі з жахами смертної тіні.","Легкий такий на поверхні води, проклята частка його на землі, і не дивиться він на дорогу садів виноградних.","Засуха і спека поглинають снігову воду: так пекло — грішників.","Нехай забуде його утроба матері, нехай ласує ним хробак; нехай не залишається про нього пам’яті; як дерево, нехай зломиться беззаконник,","який гнітить бездітну, що не народжувала, і вдові не робить добра.","Він і сильних захоплює своєю силою; він устає, і ніхто не упевнений за життя своє.","А Він дає йому все для безпеки, і він на те спирається, і очі Його бачать шляхи їхні.","Піднялися високо, — і ось, нема їх; падають і вмирають, як і всі, і, як верхівки колосся, зрізуються.","Якщо це не так, — хто викриє мене у неправді й на ніщо оберне мову мою?"],"x":{"2":"4.19.14|26.22.28","6":"10.21.15","7":"24.22.6","10":"31.58.7","12":"24.35.9","15":"24.22.13-14|26.7.9","18":"0.49.4","24":"25.36.2|25.72.18"}},{"v":["І відповів Вилдад савхеянин і сказав:","влада і страх у Нього; Він творить мир на висотах Своїх!","Чи є рахунок воїнствам Його? і над ким не сходить світло Його?","І як людині бути правою перед Богом, і як бути чистим народженому жінкою?","Ось навіть місяць, і той несвітлий, і зірки нечисті перед очима Його.","Тим менше людина, яка є червою, і син людський, який є міллю."],"x":{"1":"24.8.1|24.18.1","3":"25.102.20","4":"24.4.17|24.9.2|24.15.14","5":"24.15.15","6":"25.21.7"}},{"v":["І відповів Іов і сказав:","як ти допоміг безсилому, підтримав силу немічного!","Яку пораду подав ти немудрому і як у всій повноті пояснив справу!","Кому ти говорив ці слова, і чий дух виходив з тебе?","Рефаїми тремтять під водами, і ті, що живуть у них.","Пекло оголене перед Ним, і немає покривала Аваддону.","Він розпростер північ над порожнечою, повісив землю ні на чому.","Він тримає води в хмарах Своїх, і хмара не розпадається під ними.","Він поставив престіл Свій, розпростер над ним хмару Свою.","Межу провів над поверхнею води, до кордонів світла з темрявою.","Стовпи небес тремтять і жахаються від грози Його.","Силою Своєю хвилює море і розумом Своїм уражає його гордощі.","Від духу Його — велич неба; рука Його утворила швидкого скорпіона.","Ось, це частини путі Його; і як мало ми чули про Нього! А грім могутности Його хто може зрозуміти?"],"x":{"5":"31.14.9","6":"26.15.11|75.4.13","7":"24.38.6|75.1.3","8":"24.38.37|26.8.28","10":"24.38.8|26.8.29|32.5.22","11":"9.22.8","12":"25.88.10|31.51.10|52.8.25"}},{"v":["І продовжував Іов піднесену промову свою і сказав:","живий Бог, Який позбавив мене суду, і Вседержитель, Який засмутив душу мою,","бо, доки ще дихання моє в мені і дух Божий у ніздрях моїх,","не скажуть вуста мої неправди, і язик мій не вимовить лжі!","Далекий я від того, щоб визнати вас справедливими; доки не помру, не уступлю непорочности моєї.","Міцно тримав я правду мою і не відпущу її; не докорить мені серце моє в усі дні мої.","Ворог мій буде, як нечестивець, і той, хто повстає на мене, як беззаконник.","Бо яка надія лицемірові, коли візьме, коли вивергне Бог душу його?","Чи почує Бог крик його, коли прийде на нього лихо?","Чи буде він утішатися Вседержителем і закликати Бога повсякчас?","Сповіщу вам, що? у руці Божій; що? у Вседержителя, не приховаю.","Ось, усі ви і самі бачили; і для чого ви стільки пустословите?","Ось доля беззаконній людині від Бога, і спадщина, яку одержують від Вседержителя гнобителі.","Якщо примножуються сини його, то під меч; і нащадки його не наситяться хлібом.","Тих, що залишилися після нього, смерть зведе в гріб, і вдови їхні не будуть плакати.","Якщо він набере купи срібла, як пороху, і наготує одягу, як глини,","то він наготує, а вдягатися буде праведник, і срібло одержить собі в частку непорочний.","Він будує, як міль, дім свій і, як сторож, робить собі курінь;","лягає спати багатієм і таким не встане; відкриває очі свої, і він уже не той.","Як води, осягнуть його жахи; в ночі викраде його буря.","Підніме його східний вітер і понесе, і він швидко побіжить від нього.","Накинеться на нього і не пощадить, як би він не намагався втекти від руки його.","Сплеснуть про нього руками і засвистять над ним з місця його!"],"x":{"4":"25.14.2","6":"63.4.4","7":"24.42.7","8":"55.4.3","9":"25.17.42|26.1.28|26.28.9","10":"26.15.8","12":"25.4.3","13":"24.20.29","14":"4.28.41|24.20.10","15":"25.77.63","17":"25.48.11","19":"25.48.18","20":"24.15.20-21|24.18.11","21":"36.17.10","23":"36.25.6|44.3.19|46.2.15"}},{"v":["Так! у срібла є джерельна жила, й у золота місце, де його плавлять.","Залізо виробляється із землі; з каменю виплавляється мідь.","Людина кладе межу темряві і ретельно розшукує камінь у мороці і тіні смертній.","Виконують рудокопний колодязь у місцях, де не ступала нога, спускаються в глибину, висять і колишуться далеко від людей.","Земля, на якій виростає хліб, всередині розрита, неначе вогнем.","Камені її — місце сапфіра, і в ній піщинки золота.","Стежки туди не знає хижий птах, і не бачило її око шуліки;","не топтали її скимни, і не ходив по ній шакал.","На граніт накладає вона (людина) руку свою, з коренем перевертає гори;","у скелях просікає канали, і все дорогоцінне бачить око її;","зупиняє плин потоків і таємне виносить на світло.","Але де премудрість знаходиться? і де місце розуму?","Не знає людина ціни її, і вона не знаходиться на землі живих.","Безодня говорить: не у мені вона; і море говорить: не в мене.","Не дається вона за золото і не здобувається вона за вагу срібла;","не оцінюється вона золотом офірським, ні дорогоцінним оніксом, ні сапфіром;","не зрівнюється з нею золото і кристал, і не виміняєш її на сосуди з чистого золота.","А про корали і перли і згадувати нема чого, і придбання премудрости вище за рубіни.","Не зрівнюється з нею топаз ефіопський; чистим золотом не оцінюється вона.","Звідки ж виходить премудрість? і де місце розуму?","Прихована вона від очей усього живого і від птахів небесних утаємничена.","Аваддон і смерть говорять: вухами нашими чули ми чутку про неї.","Бог знає путь її, і Він відає місце її.","Бо Він проглядає до кінців землі і бачить під усім небом.","Коли Він вітрові визначав вагу і воді надавав міру,","коли призначав закон дощу і путь для блискавки громоносної,","тоді Він бачив її і явив її, приготував її і ще випробував її","і сказав людині: ось, страх Господній є істинна премудрість, і віддалення від зла — розум."],"x":{"15":"25.18.11|25.118.72","16":"26.8.11|29.7.9","23":"35.3.32","26":"24.38.25","28":"26.1.7"}},{"v":["І продовжував Іов піднесену промову свою і сказав:","о, якби я був, як у минулі місяці, як у ті дні, коли Бог зберігав мене,","коли світильник Його світив над головою моєю, і я при світлі Його ходив серед пітьми;","як був я у дні молодости моєї, коли милість Божа була над наметом моїм,","коли ще Вседержитель був зі мною, і діти мої навколо мене,","коли путі мої обливалися молоком, і скеля виточувала для мене струмки єлею!","коли я виходив до воріт міста і на площі ставив сідалище своє, —","юнаки, побачивши мене, ховалися, а старці вставали і стояли;","князі утримувалися від розмови і персти клали на вуста свої;","голос знатних умовкав, і язик їх прилипав до гортані їх.","Вухо, яке чуло мене, ублажало мене; око, яке бачило, величало мене,","тому що я рятував страдника, який волав, і сироту безпомічного.","Благословення того, хто гинув, сходило на мене, і серцю вдови давав я радість.","Я одягався у правду, і суд мій прикрашав мене, як мантія й вінець.","Я був очима сліпому і ногами кульгавому;","батьком був я для убогих і позов, якого я не знав, розбирав уважно.","Розтрощував я беззаконному щелепи і з зубів його виривав украдене.","І говорив я: у гнізді моєму помру, і дні мої будуть численні, як пісок;","корінь мій відкритий для води, і роса ночує на гілках моїх;","слава моя не старіє, лук мій міцний у руці моїй.","Слухали мене й очікували, і мовчали при пораді моїй.","Після слів моїх уже не розмірковували; слова мої капали на них.","Чекали на мене, як на дощ, і, як дощу пізньому, відкривали вуста свої.","Бувало, усміхнуся їм — вони не вірять; і світлого лиця мого вони не затьмарювали.","Я призначав путі їм і сидів на чолі і жив, як цар у колі воїнів, як утішитель тих, хто плаче."],"x":{"3":"24.18.6","12":"25.71.12","14":"25.131.9","15":"2.19.14","16":"24.31.18|26.29.7|30.4.10","17":"26.30.14","19":"4.28.4","20":"0.49.24"}},{"v":["А нині сміються з мене молодші за мене літами, ті, батьків яких я не погодився б помістити з псами стад моїх.","І сила рук їх до чого мені? Над ними вже минув час.","Бідністю і голодом виснажені, вони тікають у степ безводний, похмурий і спустошений;","щипають зелень біля кущів, і ягоди ялівцю — хліб їх.","Із суспільства виганяють їх, кричать на них, як на злодіїв,","щоб жили вони у вибоїнах потоків, в ущелинах землі і скелях.","Ревуть між кущами, туляться під терням.","Люди знедолені, люди без імені, непотріб землі!","Їх-то зробився я нині піснею і їжею розмов їхніх.","Вони гребують мною, віддаляються від мене і не утримуються плювати перед лицем моїм.","Оскільки Він розв’язав повід мій і вразив мене, то вони скинули з себе вузду перед лицем моїм.","З правого боку встає цей непотріб, збиває мене з ніг, направляє згубні свої шляхи до мене.","А мою стежку зіпсували: все встигли зробити для моєї погибелі, не маючи помічника.","Вони прийшли до мене, як крізь широкий пролом; з шумом кинулися на мене.","Жахи напали на мене; як вітер, розвіялася велич моя, і щастя моє зникло, як хмара.","І нині знемагає душа моя в мені: дні скорботи огорнули мене.","Уночі ниють у мені кістки мої, і жили мої не мають спокою.","Насилу знімається з мене одяг мій; краї хітона мого тиснуть мене.","Він кинув мене у бруд, і я став, як порох і попіл.","Я взиваю до Тебе, і Ти не слухаєш мене, — стою, а Ти тільки дивишся на мене.","Ти зробився жорстоким до мене, кріпкою рукою ворогуєш проти мене.","Ти підняв мене і змусив мене літати з вітром і розтрощуєш мене.","Так, я знаю, що Ти приведеш мене до смерти й у дім зібрання усіх, хто живе.","Певно, Він не простягне руки Своєї на дім кісток: чи будуть вони кричати під час свого руйнування?","Чи не плакав я про того, хто був у горі? чи не уболівала душа моя за бідних?","Коли я сподівався добра, прийшло зло; коли очікував світла, прийшла пітьма.","Мої нутрощі киплять і не перестають; зустріли мене дні печалі.","Я ходжу почорнілий, але не від сонця; встаю у зібранні і кричу.","Я став братом шакалам і другом страусам.","Моя шкіра почорніла на мені, кістки мої обгоріли від спеки.","І цитра моя зробилася сумною, і сопілка моя ридає."],"x":{"9":"24.17.6","10":"24.19.19|3.12.14","14":"24.6.4","16":"25.21.15|25.41.5|33.2.19","19":"0.18.27|24.16.15|30.10.9","20":"24.19.7","23":"75.9.27","24":"24.3.17","25":"62.12.15","26":"32.14.19","29":"25.101.7-8|31.38.14|43.1.8","30":"25.118.83","31":"40.8.10|35.4.34"}},{"v":["Завіт уклав я з очима моїми, щоб не помишляти мені про дівчину.","Яка ж доля мені від Бога з висоти? І яка спадщина від Вседержителя з небес?","Чи не для нечестивого загибель, і чи не для того, хто робить зло, напасть?","Чи не бачив Він шляхів моїх, і чи не рахував усіх моїх кроків?","Якщо я ходив у суєті, і якщо нога моя поспішала на лукавство; —","нехай зважать мене на терезах правди, і Бог дізнається про мою непорочність.","Якщо стопи мої ухилилися від шляху і серце моє ходило слідом за очима моїми, і якщо що-небудь нечисте пристало до рук моїх,","то нехай я сію, а інший їсть, і нехай паростки мої будуть викорінені.","Якщо серце моє захоплювалося жінкою і я чинив підступи біля дверей мого ближнього, —","нехай моя дружина меле на іншого, і нехай інші знущаються з неї,","тому що це — злочин, це — беззаконня, що підлягає суду;","це — вогонь, який з’їдає до знищення, який викорінив би все добро моє.","Якщо я зневажав права слуги і служниці моєї, коли вони мали суперечку зі мною,","то що став би я робити, коли Бог повстав би? І коли б Він глянув на мене, що міг би я відповісти Йому?","Чи не Він, Який створив мене в утробі, створив і його й однаково утворив нас в утробі?","Чи відмовляв я нужденним у їх проханні і чи томив очі вдови?","Чи один я з’їдав шматок мій, і чи не їв від нього і сирота?","Бо з дитинства він зростав зі мною, як з батьком, і від утроби матері моєї я піклувався про вдову.","Якщо я бачив кого, хто гинув без одягу, і бідного без покрова, —","чи не благословляли мене стегна його, і чи не був він зігрітий вовною овець моїх?","Якщо я піднімав руку мою на сироту, коли бачив допомогу собі біля воріт,","то нехай плече моє відпаде від спини, і рука моя нехай відламається від ліктя,","тому що страшне для мене покарання від Бога: перед величчю Його не устояв би я.","Чи покладав я на золоті опору мою і чи говорив скарбу: ти — надія моя?","Чи радів я, що багатство моє було великим, і коли рука моя придбала багато?","Дивлячись на сонце, як воно сяє, і на місяць, як він велично прямує,","чи спокусився я в таїні серця мого, і чи цілували вуста мої руку мою?","Це також був би злочин, що підлягає суду, тому що я відрікся б тоді від Бога Всевишнього.","Чи радів я погибелі ворога мого і чи торжествував, коли нещастя осягало його?","Не дозволяв я вустам моїм грішити прокляттям душі його.","Чи не говорили люди намету мого: о, якби ми м’ясом його не наситилися?","Подорожній не ночував на вулиці; двері мої я відчиняв перехожому.","Якби я ховав провини мої, як людина, приховуючи в грудях моїх пороки мої,","то я боявся б великої громади, і презирство одноплемінників страшило б мене, і я мовчав би і не виходив би за двері.","О, якби хто вислухав мене! Ось моє бажання, щоб Вседержитель відповів мені, і щоб захисник мій зробив запис.","Я носив би його на плечах моїх і покладав би його, як вінець;","оголосив би йому число кроків моїх, зблизився б з ним, як із князем.","Якщо волала проти мене земля моя і скаржилися на мене борозни її;","якщо я їв плоди її без оплати й обтяжував життя хліборобів,","то нехай замість пшениці виростає осот і замість ячменя кукіль. Слова Іова скінчилися."],"x":{"1":"0.34.1-2|30.9.5|50.5.28","4":"24.23.10|24.34.21|25.138.3","7":"25.7.4","8":"2.26.16|4.28.30:38","9":"24.24.15","10":"4.28.30","11":"0.38.24|2.20.10","12":"31.47.14","13":"66.6.9|68.4.1","16":"58.3.17|55.2.15-16","17":"52.14.13","18":"24.29.16|30.4.10","19":"31.58.7","20":"4.24.13","21":"31.58.4","22":"48.11.17","23":"0.50.19","24":"25.61.11|51.10.24","26":"4.4.19|36.8.16","27":"10.19.18","28":"73.1.16","29":"26.24.17","32":"0.19.2|62.12.13|75.13.2","33":"0.3.8|38.6.7","39":"55.5.11"}},{"v":["Коли ті три мужі перестали відповідати Іову, тому що він був правий в очах своїх,","тоді запалав гнів Елиуя, сина Варахиїлового, вузитянина з племені Рамового: запалав гнів його на Іова за те, що він виправдовував себе більше, ніж Бога,","а на трьох друзів його запалав гнів його за те, що вони не знайшли, що відповісти, а тим часом звинувачували Іова.","Елиуй чекав, поки Іов говорив, тому що вони літами були старші за нього.","Коли ж Елиуй побачив, що немає відповіді з вуст тих трьох мужів, тоді запалав гнів його.","І відповів Елиуй, син Варахиїлів, вузитянин, і сказав: я молодий літами, а ви — старці; тому я ніяковів і боявся оголошувати вам свою думку.","Я говорив сам собі: нехай говорять дні, і багатоліття повчає мудрости.","Але дух у людині і подих Вседержителя дає їй розуміння.","Не багаторічні тільки мудрі, і не старі розуміють правду.","Тому я говорю: вислухайте мене, оголошу вам мою думку і я.","Ось, я очікував слів ваших, — вслуховувався в судження ваші, доки ви придумували, що? сказати.","Я пильно дивився на вас, і ось ніхто з вас не викриває Іова і не відповідає на слова його.","Не скажіть: ми знайшли мудрість: Бог спростує його, а не людина.","Якби він звертав слова свої до мене, то я не вашими словами відповідав би йому.","Злякалися, не відповідають більше; перестали говорити.","І як я чекав, а вони не говорять, зупинилися і не відповідають більше,","то я відповім з мого боку, висловлю мою думку і я,","бо я переповнений словами, і дух у мені розпирає мене.","Ось, утроба моя, як вино невідкрите: вона готова прорватися, подібно до нових міхів.","Виговорюсь, і буде легше мені; відкрию вуста мої і відповім.","На лице людини дивитися не буду і ніякій людині лестити не стану,","тому що я не вмію лестити: зараз убий мене, Творче мій."],"x":{"1":"24.2.11","2":"24.35.2","6":"24.15.10","7":"24.12.12","8":"31.11.2|26.2.6","9":"37.2.21|25.118.100","18":"32.20.9|43.3.8","21":"32.17.16"}},{"v":["Отже, слухай, Іове, промову мою і прислухайся до кожного слова мого.","Ось, я відкриваю вуста мої, язик мій говорить у гортані моїй.","Слова мої від щирости мого серця, і вуста мої вимовлять знання чисте.","Дух Божий створив мене, і подих Вседержителя дав мені життя.","Якщо можеш, відповідай мені і стань переді мною.","Ось я, за бажанням твоїм, замість Бога. Я створений також із пороху;","тому страх переді мною не може знітити тебе, і рука моя не буде важкою для тебе.","Ти говорив у вуха мої, і я чув звук слів:","чистий я, без пороку, невинний я, і немає в мені неправди;","а Він знайшов звинувачення проти мене і вважає мене Своїм супротивником;","поставив ноги мої в колоду, спостерігає за всіма путями моїми.","Ось у цьому ти неправий, відповідаю тобі, тому що Бог вище людини.","Для чого тобі змагатися з Ним? Він не дає звіту ні в яких ділах Своїх.","Бог говорить один раз і, якщо того не помітять, удруге:","уві сні, у нічному видінні, коли сон находить на людей, під час дрімоти на постелі.","Тоді Він відкриває в людини вухо і закарбовує Своє наставляння,","щоб відвести людину від якого-небудь наміру і віддалити від неї гордість,","щоб відвести душу її від прірви і життя її від ураження мечем.","Або він врозумляється хворобою на постелі своїй і тяжким болем у всіх кістках своїх, —","і життя її відвертається від хліба і душа її від улюбленої їжі.","Плоть на ній пропадає, так що її не видно, і показуються кістки її, яких не було видно.","І душа її наближається до могили і життя її — до смерті.","Якщо є у неї ангел-наставник, один з тисячі, щоб показати людині пряму путь її, —","Бог змилосердиться над нею і скаже: звільни її від могили; Я знайшов умилостивлення.","Тоді тіло її зробиться свіжішим, ніж у молодості; вона повернеться до днів юности своєї.","Буде молитися Богу, і Він — милостивий до неї; з радістю дивиться на лице її і повертає людині праведність її.","Він буде дивитися на людей і говорити: грішив я і спотворював правду, і не воздано мені;","Він визволив душу мою від могили, і життя моє бачить світло.","Ось, усе це робить Бог двічі-тричі з людиною,","щоб відвести душу її від могили й освітити її світлом живих.","Прислухайся, Іове, слухай мене, мовчи, і я буду говорити.","Якщо маєш, що сказати, відповідай; говори, тому що я бажав би твого виправдання;","якщо ж ні, то слухай мене: мовчи, і я навчу тебе мудрости."],"x":{"4":"0.1.2|25.32.6|25.103.30","6":"24.10.9|27.12.7","9":"24.10.7|24.16.17|24.23.10","10":"24.13.24|24.19.11","11":"24.13.27","12":"24.34.7","14":"3.23.19|8.15.29","15":"24.4.13","16":"9.7.27|31.50.4","20":"25.106.18","23":"0.48.16|48.3.1|71.2.5","24":"25.90.15|31.43.1-2|38.13.14","26":"25.49.15|31.58.9","28":"63.11.32","30":"25.55.14|25.102.4"}},{"v":["І продовжував Елиуй і сказав:","вислухайте, мудрі, слова мої, і прихиліть до мене вухо, розсудливі!","Бо вухо розрізняє слова, як гортань розрізняє смак їжі.","Співставляємо між собою міркування і розпізнаємо, що добре.","Ось, Іов сказав: я правий, але Бог позбавив мене суду.","Чи повинен я говорити лжу на правду мою? Моя рана незцілима без провини.","Чи є така людина, як Іов, який п’є знущання, як воду,","вступає у співтовариство з тими, хто чинить беззаконня і ходить з людьми нечестивими?","Тому що він сказав: немає користи для людини у благовгоджанні Богу.","Отже, послухайте мене, мужі мудрі! Не може бути в Бога неправда або у Вседержителя неправосуддя,","бо Він за ділами людини чинить з нею і за путями чоловіка відплачує йому.","Істинно, Бог не чинить неправди і Вседержитель не спотворює суд.","Хто, крім Нього, промишляє про землю? І хто керує всією вселенною?","Якби Він звернув серце Своє до Себе і взяв до Себе дух її і подих її,","миттєво загинула б усяка плоть, і людина повернулася б у порох.","Отже, якщо ти маєш розум, то слухай це і зважай на слова мої.","Чи може ненависник правди володарювати? І чи можеш ти звинуватити Всеправедного?","Чи можна сказати цареві: ти — нечестивець, і князям: ви — беззаконники?","Але Він не дивиться і на лиця князів і не дає переваги багатому над бідним, тому що усі вони діло рук Його.","Раптово вони помирають; серед ночі народ обуриться, і вони зникають; і сильних виганяють не силою.","Тому що очі Його над путями людини, і Він бачить усі кроки її.","Немає пітьми, ні тіні смертної, де могли б сховатися ті, що чинять беззаконня.","Тому Він уже не вимагає від людини, щоб вона йшла на суд з Богом.","Він скрушає сильних без дослідження і поставляє інших на їхні місця;","тому що Він робить відомими діла їхні і скидає їх уночі, і вони знищуються.","Він уражає їх, як беззаконних людей, перед очима інших,","за те, що вони відвернулися від Нього і не зрозуміли всіх шляхів Його,","так що дійшло до Нього волання бідних, і Він почув стогін пригноблених.","Чи дарує Він тишу, хто може збурити? чи ховає Він лице Своє, хто може побачити Його? Чи буде це для народу, чи для однієї людини,","щоб не царював лицемір на спокусу народу.","До Бога слід говорити: я потерпів, більше не буду грішити.","А чого я не знаю, Ти навчи мене; і якщо я зробив беззаконня, більше не буду.","Чи за твоїм міркуванням Він повинен відплачувати? І оскільки ти відкидаєш, то тобі варто обирати, а не мені; говори, що знаєш.","Люди розумні скажуть мені, і муж мудрий, який слухає мене:","Іов нерозумно говорить, і слова його не мають сенсу.","Я бажав би, щоб Іов цілком був випробуваний, за відповідями його, які властиві людям нечестивим.","Інакше він до гріха свого додасть відступлення, буде рукоплескати між нами і ще більше наговорить проти Бога."],"x":{"3":"24.12.11","5":"24.13.18|24.23.10|24.35.2","6":"24.6.4","7":"24.15.16","9":"24.9.22|49.3.14","10":"24.8.3|24.36.23","11":"26.24.12|62.2.6","13":"24.38.4","14":"25.103.29","15":"0.3.19","19":"4.10.17|13.19.7|29.6.7|30.35.12|54.10.34|56.1.17|62.2.11|65.2.6|66.6.9","24":"26.5.21","25":"24.27.20","27":"25.27.5","28":"25.9.13","29":"53.14.27|62.8.34","30":"38.13.11"}},{"v":["І продовжував Елиуй і сказав: чи","вважаєш ти справедливим, що сказав: я правіший за Бога?","Ти сказав: яка користь мені? і який прибуток я мав би перед тим, як коли б я і грішив?","Я відповім тобі і твоїм друзям з тобою:","поглянь на небо і дивися; поглянь на хмари, вони вище тебе.","Якщо ти грішиш, що робиш ти Йому? і якщо злочини твої збільшуються, що заподіюєш ти Йому?","Якщо ти праведний, що даєш Йому? або що одержує Він від руки твоєї?","Нечестя твоє відноситься до людини, як ти, і праведність твоя до сина людського.","Від безлічі гнобителів стогнуть гноблені, і від руки сильних волають.","Але ніхто не говорить: де Бог, Творець мій, Який дає пісні вночі,","Який навчає нас більше, ніж худобу земну, і напоумлює нас більше, ніж птахів небесних?","Там вони волають, і Він не відповідає їм, з причини гордости злих людей.","Але неправда, що Бог не чує і Вседержитель не дивиться на це.","Хоча ти сказав, що ти не бачиш Його, але суд перед Ним, і — чекай на нього.","Але нині, тому що гнів Його не відвідав його і він не пізнав його у всій суворості,","Іов і відкрив легковажно вуста свої і нерозважливо марнує слова."],"x":{"2":"24.32.2|24.34.5","6":"32.7.19","7":"24.22.3","9":"24.24.12","10":"25.41.9","11":"57.2.12","12":"24.27.9|26.15.29","13":"31.1.15|53.9.31","14":"24.23.9|27.3.17|27.12.14"}},{"v":["І продовжував Елиуй і сказав:","почекай мене трохи, і я покажу тобі, що я маю ще дещо сказати за Бога.","Почну мої міркування здалеку, і воздам Творцю моєму справедливість,","тому що слова мої точно не лжа: перед тобою — довершений у пізнаннях.","Ось, Бог могутній і не нехтує сильним міцністю серця;","Він не підтримує нечестивих і відплачує належне пригнобленим;","Він не відвертає очей Своїх від праведників, але з царями назавжди посаджує їх на престолі, і вони підносяться.","Якщо ж вони закуті ланцюгами й утримуються в кайданах біди,","то Він вказує їм на діла їхні і на беззаконня їхні, тому що примножилися,","і відкриває їх вухо для напоумлення і говорить їм, щоб вони відступили від нечестя.","Якщо послухають і будуть служити Йому, то проведуть дні свої у благополуччі і літа свої в радості;","якщо ж не послухають, то загинуть від стріли і помруть у нерозумі.","Але лицеміри живлять у серці гнів і не взивають до Нього, коли Він заковує їх у кайдани;","тому душа їх помирає у молодості і життя їх із блудниками.","Він спасає бідного від лиха його й у пригнобленні відкриває вухо його.","І тебе вивів би Він з тісноти на простір, де немає стиснення, і те, що ставиться на стіл твій, було б наповнене жиром;","але ти сповнений судженнями нечестивих: судження й осудження — близькі.","Нехай не вразить тебе гнів Божий покаранням! Великий викуп не спасе тебе.","Чи дасть Він яку ціну твоєму багатству? Ні, — ні золоту і ніякому скарбу.","Не бажай тієї ночі, коли народи знищуються на своєму місці.","Бережися, не схиляйся до нечестя, якому ти віддав перевагу перед стражданнями.","Бог високий могутністю Своєю, і хто такий, як Він, наставник?","Хто вкаже Йому путь Його; хто може сказати: Ти чиниш несправедливо?","Пам’ятай про те, щоб звеличувати діла Його, які люди бачать.","Усі люди можуть бачити їх; людина може бачати їх здаля.","Ось, Бог великий, і ми не можемо пізнати Його; число років Його недослідиме.","Він збирає краплі води; вони в безлічі виливаються дощем:","із хмар падають і виливаються рясно на людей.","Хто може також осягнути простір хмар, тріщання намету Його?","Ось, Він посилає на нього світло Своє і покриває дно моря.","Звідти Він судить народи, дає їжу в достатку.","Він ховає в долонях Своїх блискавку і повеліває їй, кого вразити.","Тріскотіння її дає звістку про неї; худоба також відчуває, що відбувається."],"x":{"3":"25.50.6","4":"64.2.17","7":"25.32.18|25.112.7","8":"25.106.10","10":"24.33.16","11":"13.33.13","12":"52.19.42","13":"50.23.27","15":"25.34.10|31.66.2","16":"13.18.31|25.17.20","18":"8.12.3|26.11.4","21":"75.6.11","22":"8.3.18","26":"71.6.16|25.101.28|37.6.26","29":"25.103.2|26.8.28"}},{"v":["І від цього тремтить серце моє і зрушилося з місця свого.","Слухайте, слухайте голос Його і грім, що виходить з вуст Його.","Під усім небом перекоти його, і блищання його — до країв землі.","За ним гримить голос; гримить Він гласом величі Своєї і не зупиняє його, коли голос Його почутий.","Дивно гримить Бог гласом Своїм, робить діла великі, для нас незбагненні.","Бо снігу Він говорить: будь на землі; однаково дрібний дощ і великий дощ у Його владі.","Він кладе печать на руку кожної людини, щоб усі люди знали діла Його.","Тоді звір іде в притулок і залишається у своїх лігвах.","З півдня приходить буря, з півночі — холоднеча.","Від подиху Божого утворюється лід, і поверхня води стискується.","Також вологою Він наповнює хмари, і хмари випромінюють світло Його,","і вони спрямовуються за намірами Його, щоб виконати те, що Він повелить їм на лиці населеної землі.","Він повеліває їм іти або для покарання, або на благовоління, або для помилування.","Слухай це, Іове; стій і розумій дивні діла Божі.","Чи знаєш, як Бог розпоряджається ними і повеліває світлу блищати із хмари Своєї?","Чи розумієш рівновагу хмар, дивне діло Найдосконалішого у знанні?","Як нагрівається твій одяг, коли Він заспокоює землю від півдня?","Чи ти з Ним розпростер небеса, тверді, як відлите дзеркало?","Навчи нас, що сказати Йому? Ми в цій пітьмі нічого не можемо зрозуміти.","Чи буде сповіщено Йому, що я говорю? Чи сказав хто, що те, що сказано, доноситься Йому?","Тепер не видно яскравого світла у хмарах, але пронесеться вітер і розчистить їх.","Світла погода приходить від півночі, і навколо Бога страшна велич.","Вседержитель! ми розумом не осягаємо Його. Він великий силою, судом і повнотою правосуддя. Він нікого не гнітить.","Тому нехай благоговіють перед Ним люди, і нехай тремтять перед Ним усі мудрі серцем!"],"x":{"3":"25.17.15","5":"25.28.3|25.76.19|24.5.9","6":"25.32.9|25.147.5","8":"25.103.22","14":"25.110.2","18":"31.44.24","23":"24.9.4|24.12.13:16|25.144.3"}},{"v":["[Коли Елиуй перестав говорити,] Господь відповів Іову із бурі і сказав:","хто цей, що затьмарює Провидіння словами без сенсу?","Опережи нині стегна твої, як муж: Я буду запитувати тебе, і ти пояснюй Мені:","де був ти, коли Я заклав основи землі? Скажи, якщо знаєш.","Хто поклав міру її, якщо знаєш? або хто протягував по ній шнур?","На чому затверджені основи її, або хто поклав наріжний камінь її,","при загальному торжестві ранкових зірок, коли всі сини Божі викликували від радости?","Хто зачинив море воротами, коли воно виверглося, вийшло ніби з утроби,","коли Я хмари зробив одежею його й імлу пеленами його,","й утвердив йому Моє визначення, і поставив засуви і ворота,","і сказав: сюди дійдеш і не перейдеш, і тут межа гордовитим хвилям твоїм?","Чи давав ти коли в житті своєму накази ранку і чи вказував зорі місце її,","щоб вона охопила краї землі і струсила з неї нечестивих,","щоб земля змінилася, як глина під печаткою, і стала, як різнобарвний одяг,","щоб відібралося у нечестивих світло їх і зухвала рука їх скрушилася?","Чи сходив ти у глибину моря і чи входив у дослідження безодні?","Чи відчинялися для тебе врата смерти, і чи бачив ти врата тіні смертної?","Чи оглянув ти широту землі? Поясни, якщо знаєш усе це.","Де путь до оселі світла, і де місце темряви?","Ти, звичайно, доходив до меж її і знаєш дорогу до дому її.","Ти знаєш це, тому що ти вже був тоді народжений, і число днів твоїх дуже велике.","Чи входив ти у сховища снігу і чи бачив скарбниці граду,","які бережу Я на час смутний, на день битви і війни?","Яким шляхом розливається світло і розноситься східний вітер по землі?","Хто проводить протоки для виливання води і шлях для громоносної блискавки,","щоб ішов дощ на землю безлюдну, на пустелю, де немає людини,","щоб насичувати пустелю і степ і пробуджувати трав’яні зародки до зростання?","Чи є у дощу батько? або хто народжує краплі роси?","З чиєї утроби виходить лід, та іній небесний, — хто народжує його?","Води, як камінь, міцніють, і поверхня безодні замерзає.","Чи можеш ти зв’язати вузол Хима і порушити узи Кесиль?","Чи можеш виводити сузір’я у свій час і вести Ас (зірницю) з її дітьми?","Чи знаєш ти устави неба, чи можеш встановити володіння його на землі?","Чи можеш піднести голос твій до хмар, щоб вода в достатку покрила тебе?","Чи можеш посилати блискавки, і чи підуть вони і чи скажуть тобі: ось ми?","Хто вклав мудрість у серце, або хто дав сенс розуму?","Хто може обчислити хмари своєю мудрістю й утримати сосуди неба,","коли порох перетворюється на бруд і брили злипаються?","Чи ти ловиш здобич левиці і насичуєш молодих левів,","коли вони лежать у барлогах або ховаються під тінню у засідці?","Хто готує ворону корм його, коли пташенята його кричать до Бога, блукаючи без їжі?"],"x":{"1":"1.19.18|10.19.11|36.1.4","3":"24.40.2","4":"0.1.1","5":"26.30.4","6":"24.26.7","7":"37.7.10","8":"24.26.10","10":"26.8.29|25.103.9","15":"24.18.5-6|36.30.22","16":"25.76.20","17":"24.10.21|31.14.9","21":"25.38.5","23":"1.9.14-15|5.10.11","25":"25.134.7|32.10.13","27":"25.106.35","28":"24.5.10|24.36.27|32.14.22","31":"24.9.9|31.13.10","33":"32.31.35","36":"24.32.8","37":"24.26.8","39":"25.103.21","41":"25.146.9"}},{"v":["Чи знаєш ти час, коли народжуються дикі кози на скелях, і чи помічав пологи ланей?","чи можеш обчислити місяці вагітности їх? і чи знаєш час пологів їх?","Вони вигинаються, народжуючи дітей своїх, викидаючи свої ноші;","діти їх приходять у силу, ростуть на полі, йдуть і не повертаються до них.","Хто випустив дикого осла на волю, і хто розв’язав пута онагру,","якому степ Я призначив домом і солончаки — житлом?","Він насміхається над міською багатолюдністю і не чує криків погонича,","по горах шукає собі їжу і ганяється за всякою зеленню.","Чи захоче єдиноріг служити тобі і чи переночує біля ясел твоїх?","Чи можеш мотузкою прив’язати єдинорога до борозни, і чи стане він боронити за тобою поле?","Чи будеш надіятися на нього, тому що в нього сила велика, і чи даси йому роботу твою?","Чи повіриш йому, що він насіння твоє поверне і складе на тік твій?","Чи ти дав красиві крила павичу і пера і пух страусу?","Він залишає яйця свої на землі, і на піску зігріває їх,","і забуває, що нога може роздавити їх і польовий звір може розтоптати їх;","він жорстокий до дітей своїх, немов не до своїх, і не боїться, що праця його буде даремна;","тому що Бог не дав йому мудрости і не наділив його глуздом;","а коли підніметься на висоту, посміється з коня і вершника його.","Чи ти дав коню силу і наділив шию його гривою?","Чи можеш ти злякати його, як сарану? Хропіння ніздрів його — жах;","риє ногою землю і захоплюється силою; йде назустріч зброї;","він глузує з небезпеки і не боїться і не відвертається від меча;","сагайдак гуркотить над ним, блискотить спис і дротик;","у пориві і люті він ковтає землю і не може стояти при звуці труби;","при трубному звуці він подає голос: гу! гу! і здалеку чує битву, гучні голоси вождів і крик.","Чи твоєю мудрістю літає яструб і спрямовує крила свої на південь?","Чи за твоїм словом піднімається орел і влаштовує на висоті гніздо своє?","Він живе на скелі і ночує на зубцях скелі і на місцях неприступних;","звідти видивляється собі їжу: очі його дивляться далеко;","пташенята його п’ють кров, і де труп, там і він.","І продовжував Господь і сказав Іову:","чи буде той, хто змагається з Вседержителем, ще вчити? Той, хто викриває Бога, нехай відповідає Йому.","І відповів Іов Господу і сказав:","ось, я нікчемний; що буду я відповідати Тобі? Руку мою покладаю на вуста мої.","Один раз я говорив, — тепер відповідати не буду, навіть двічі, але більше не буду."],"x":{"6":"25.106.34","24":"26.21.31"}},{"v":["І відповів Господь Іову з бурі і сказав:","опережи, як муж, стегна твої: Я буду запитувати тебе, а ти пояснюй Мені.","Ти хочеш відкинути суд Мій, звинуватити Мене, щоб виправдати себе?","Чи така в тебе сила, як у Бога? І чи можеш загриміти голосом, як Він?","Прикрась же себе величчю і славою, одягнись у блиск і красу;","вилий лють гніву твого, подивися на все горде і смири його;","глянь на всіх зарозумілих і принизь їх, і скруши нечестивих на місцях їх;","зарий усіх їх у землю й лиця їх покрий темрявою.","Тоді і Я визнаю, що правиця твоя може спасати тебе.","Ось бегемот, якого Я створив, як і тебе; він їсть траву, як віл;","ось, його сила в стегнах його і міцність його у м’язах черева його;","повертає хвостом своїм, як кедром; жили ж на стегнах його переплетені;","ноги в нього, як мідні труби; кістки в нього, як залізні прути;","це — верх шляхів Божих; тільки Той, Хто створив його, може наблизити до нього меч Свій;","гори приносять йому їжу, і там усі звірі польові грають;","він лягає під тінистими деревами, під дахом очерету й у болотах;","тінисті дерева покривають його своєю тінню; верби при струмках оточують його;","ось, він п’є з ріки і не поспішає; залишається спокійним, хоч би Йордан побіг до рота його.","Чи візьме хто його на очах його і чи проколе йому ніс багром?","Чи можеш ти вудкою витягти левиафана і мотузкою схопити за язик його?","чи вдінеш кільце в ніздрі його? чи проколеш голкою щелепу його?","чи буде він довго благати тебе і чи буде говорити з тобою лагідно?","чи укладе він договір з тобою, і чи візьмеш його назавжди собі за раба?","чи станеш забавлятися ним, як пташкою, і чи зв’яжеш його для дівчаток твоїх?","чи будуть продавати його товариші ловитви, чи розділять його між хананейськими купцями?","чи можеш простромити шкіру його списом і голову його рибальською острогою?","Клади на нього руку твою, і пам’ятай про ту боротьбу: більше не будеш."],"x":{"2":"24.38.3"}},{"v":["Надія марна: чи не впадеш від одного погляду його?","Немає настільки відважного, який насмілився б потурбувати його; хто ж може устояти перед Моїм лицем?","Хто випередив Мене, щоб Мені винагородити його? під усім небом усе Моє.","Не промовчу про члени його, про силу і красиву пропорційність їх.","то може відкрити верх одягу його, хто підійде до подвійних щелеп його?","Хто може відчинити двері лиця його? коло зубів його — жах;","міцні щити його — краса; вони скріплені ніби твердою печаткою;","один іншого торкається близько, так що і повітря не проходить між ними;","один з іншим лежать щільно, зчепилися і не розсуваються.","Від його чхання показується світло; очі в нього, як вії зорі;","з пащі його виходять пломені, вискакують вогненні іскри;","з ніздрів його виходить дим, як з киплячого горщика або казана.","Подих його розжарює вугілля, і з пащі його виходить полум’я.","На шиї його живе сила, і перед ним біжить жах.","М’ясисті частини тіла його з’єднані між собою твердо, не здригнуться.","Серце його тверде, як камінь, і жорстке, як нижнє жорно.","Коли він піднімається, силачі в страху, зовсім губляться від жаху.","Меч, що доторкнеться до нього, не встоїть, ні спис, ні дротик, ні лати.","Залізо він вважає за солому, мідь — за гниле дерево.","Дочка (стріла) лука не змусить його тікати; а камені із пращі для нього полова.","Булава вважається у нього за соломину; зі свисту дротика він сміється.","Під ним гострі камені, і він на гострих каменях лежить у бруді.","Він кип’ятить безодню, як казан, і море перетворює на киплячу мазь;","залишає за собою світлу стежку; безодня здається сивиною.","Немає на землі подібного до нього; він створений безстрашним;","на все високе дивиться сміливо; він цар над усіма синами гордости."],"x":{"1":"32.50.44","3":"31.19.5|4.10.14|25.23.1"}},{"v":["І відповів Іов Господу і сказав:","знаю, що Ти все можеш, і що намір Твій не може бути зупинений.","Хто цей, що потьмарює Провидіння, нічого не розуміючи? — Так, я говорив про те, чого не розумів, про діла дивні для мене, яких я не знав.","Вислухай, взивав я, і я буду говорити, і що буду запитувати в Тебе, поясни мені.","Я чув про Тебе слухом вуха; тепер же мої очі бачать Тебе;","тому я відрікаюся і розкаююся в поросі і попелі.","І було після того, як Господь сказав слова ті Іову, сказав Господь Елифазу феманитянину: горить гнів Мій на тебе і на двох друзів твоїх за те, що ви говорили про Мене не так вірно, як раб Мій Іов.","Отже, візьміть собі сім тельців і сім баранів і підіть до раба Мого Іова і принесіть за себе жертву; і раб Мій Іов помолиться за вас, тому що тільки лице його Я прийму, щоб не відкинути вас за те, що ви говорили про Мене не так вірно, як раб Мій Іов.","І пішли Елифаз феманитянин і Вилдад савхеянин і Софар наамитянин, і зробили так, як Господь повелів їм, — і Господь прийняв лице Іова.","І повернув Господь втрату Іова, коли він помолився за друзів своїх; і дав Господь Іову вдвічі більше того, що він мав раніше.","Тоді прийшли до нього всі брати його й усі сестри його і всі колишні знайомі його, і їли з ним хліб у домі його, і тужили з ним, і утішали його за все зло, яке Господь навів на нього, і дали йому кожен по кеситі і по золотому кільцю.","І благословив Бог останні дні Іова більше, ніж минулі: у нього було чотирнадцять тисяч дрібної худоби, шість тисяч верблюдів, тисяча пар волів і тисяча ослиць.","І було в нього сім синів і три дочки.","І нарік він ім’я першій Емима, ім’я другій — Кассія, а ім’я третій — Керенгаппух.","І не було на всій землі таких прекрасних жінок, як дочки Іова, і дав їм батько їхню спадщину між братами їхніми.","Після того Іов жив сто сорок років, і бачив синів своїх і синів синів до четвертого роду;","і помер Іов у старості, насичений днями*."],"x":{"2":"0.18.14|50.19.26","3":"24.38.2|25.39.6","5":"31.55.3|52.5.8","7":"24.2.11|24.27.7","8":"0.20.7|55.5.16","10":"4.30.3|75.11.34|51.10.30","12":"24.1.3","16":"26.3.16"},"n":{"17":["У слов’янській Біблії до книги Іова є такий додаток: «Написано, що він знову постане з тими, кого воскресить Господь. Про нього тлумачиться в Сирській книзі, що жив він у землі Авситидійській на кордонах Ідумеї й Аравії: раніше ж було ім’я йому Іовав. Узявши дружину аравитянку, породив сина, якому ім’я Еннон. Походив він від батька Зарефа, синів Ісавових син, матері ж Воссори, так що був він п’ятим від Авраама. І ці царі, які царювали в Едомі, якою країною і він володів: перший Валак, син Веора, і ім’я місту його Деннава; після ж Валака Іовав, названий Іовом; після цього Ассом, ігемон з Феманитської країни; останній Адад, син Варада, який уразив Мадіама на полі Моава, — і ім’я місту його Гефем. Друзі ж, які прийшли до нього, Елифаз (син Софана) від синів Ісавових, цар Феманський, Валдад (син Амнона ховарського) савхейський володар, Софар Минейський цар. (Феман син Елифаза, правитель Ідумеї. Про нього говориться в книзі Сирській, що він жив у землі Авситидійській, біля берегів Євфрату; раніше ім’я його було Іовав, батько ж його був Зареф, від сходу сонця.)»"]}}];
export default C;
